// The seed AST is deserialized from `program.ast.json` onto the compile arena
// in the backend's main() — it is already writable heap memory, so the
// metacircular pipeline's in-place mutations (`@constCast` template inline_body
// writes, auto-discharge binding-annotation stamps) are safe with no clone.
// (This is why the old rodata-SIGSEGV heap-clone hack is gone: there is no
// longer a `pub const PROGRAM_AST` in read-only `.rodata` to mutate.)
const ctx = CompilerContext{
    .ast = program_ast,
    .original_ast = program_ast,  // Initially same as ast, preserved across filtering
    .allocator = allocator,
    .errors = std.ArrayList(CompilerError){},
    .warnings = std.ArrayList(CompilerWarning){},
    .error_policy = .collect_all,
    .current_pass = "init",
    .passes_completed = 0,
    .tap_registry = null,
};
return ctx;

const metrics = std.fmt.allocPrint(
    allocator,
    "Passes: {d} (flow-based: frontend, analysis, emission)",
    .{passes_completed}
) catch "Passes: <unknown> (flow-based: frontend, analysis, emission)";
return metrics;

// Serialize AST to JSON
const ast_serializer = @import("ast_serializer");
var serializer = ast_serializer.AstSerializer.init(ctx.allocator) catch unreachable;
defer serializer.deinit();

const json_output = serializer.serializeToJson(ctx.ast) catch unreachable;

// Print to stderr with separator showing which dump this is
std.debug.print("=== AST DUMP: {s} ===\n{s}\n", .{flag, json_output});

const tp = @import("template_processor");
// Thread the build language into the per-call template pass. Per-call
// (`|template|`) procs are spliced inline HERE, upstream of the emitter's
// variant pick — so the renderer, not the emitter, must select the
// `|zig` vs `|js` body. CompilerEnv.lang is the user's `--lang` flag
// ("zig" default, "js" for JS builds), globally available in the backend.
tp.processTemplateProcs(ctx.ast, ctx.allocator, CompilerEnv.lang) catch unreachable;

var updated_ctx = ctx;
updated_ctx.passes_completed += 1;
updated_ctx.current_pass = "process_template_procs";
return updated_ctx;

const backend_output = @import("backend_output_emitted.zig");
var updated_ctx = ctx;
if (@hasDecl(backend_output, "run_pass")) {
    const pre_ast = backend_output.run_pass("pre", ctx.ast, ctx.allocator) catch |err| {
        log.err("FATAL: pre-stage transform pass failed ({s}). The pipeline cannot continue with a partially-transformed AST.\n", .{@errorName(err)});
        @panic("pre-stage transform pass failed — see error above");
    };
    updated_ctx.ast = pre_ast;
}
updated_ctx.passes_completed += 1;
updated_ctx.current_pass = "run_pre_transforms";
return updated_ctx;

const ast_mod = @import("ast");
const main_mod = ctx.ast.main_module_name;
const alloc = ctx.allocator;

var updated_ctx = ctx;

const S = struct {
    // Build a set of "module\x00event" keys from every event_decl (recursing
    // module_decls). Collected from original_ast — the unfiltered AST — so the
    // membership check is complete regardless of emit-mode filtering.
    fn collect(items: []const ast_mod.Item, set: *std.StringHashMap(void), a: std.mem.Allocator) void {
        for (items) |*item| {
            switch (item.*) {
                .event_decl => |*e| {
                    if (e.path.segments.len == 0) continue;
                    const mq = e.path.module_qualifier orelse continue;
                    const seg = e.path.segments[e.path.segments.len - 1];
                    const key = std.fmt.allocPrint(a, "{s}\x00{s}", .{ mq, seg }) catch continue;
                    set.put(key, {}) catch {};
                },
                .module_decl => |*m| collect(m.items, set, a),
                else => {},
            }
        }
    }

    fn has(set: *std.StringHashMap(void), mod: []const u8, seg: []const u8, a: std.mem.Allocator) bool {
        const key = std.fmt.allocPrint(a, "{s}\x00{s}", .{ mod, seg }) catch return false;
        defer a.free(key);
        return set.contains(key);
    }

    // Does this invocation open a vocabulary — carry a `[with]` annotation?
    fn opensWith(inv: *const ast_mod.Invocation) bool {
        for (inv.annotations) |ann| {
            if (std.mem.eql(u8, ann, "with")) return true;
        }
        return false;
    }

    fn addTarget(mq: ?[]const u8, targets: *std.ArrayList([]const u8), seen: *std.StringHashMap(void), a: std.mem.Allocator) void {
        const m = mq orelse return;
        if (seen.contains(m)) return;
        seen.put(m, {}) catch {};
        targets.append(a, m) catch {};
    }

    // Gather every `[with]` target opened anywhere in a flow subtree — the head
    // AND every mid-chain step, now that the parser hangs the annotation on the
    // step's Invocation. Distinct by module.
    fn gatherNode(node: *const ast_mod.Node, targets: *std.ArrayList([]const u8), seen: *std.StringHashMap(void), a: std.mem.Allocator) void {
        switch (node.*) {
            .invocation => |*inv| {
                if (opensWith(inv)) addTarget(inv.path.module_qualifier, targets, seen, a);
            },
            .label_with_invocation => |*lwi| {
                if (opensWith(&lwi.invocation)) addTarget(lwi.invocation.path.module_qualifier, targets, seen, a);
            },
            .conditional_block => |*cb| for (cb.nodes) |*n| gatherNode(n, targets, seen, a),
            .foreach => |*fe| for (fe.branches) |*b| for (b.body) |*c| gatherCont(c, targets, seen, a),
            .conditional => |*cond| for (cond.branches) |*b| for (b.body) |*c| gatherCont(c, targets, seen, a),
            .switch_result => |*sr| for (sr.branches) |*b| for (b.body) |*c| gatherCont(c, targets, seen, a),
            else => {},
        }
    }

    fn gatherCont(cont: *const ast_mod.Continuation, targets: *std.ArrayList([]const u8), seen: *std.StringHashMap(void), a: std.mem.Allocator) void {
        if (cont.node) |*n| gatherNode(n, targets, seen, a);
        for (cont.continuations) |*nested| gatherCont(nested, targets, seen, a);
    }

    // Resolve one bare name against the active `[with]` targets.
    //   .local     — resolves in the main module; never shadowed
    //   .unknown   — no active target owns it; leave for the downstream KORU040
    //   .resolved  — exactly one target owns it; restamped in place here
    //   .ambiguous — two or more own it; caller raises the KORU140 pick-wall
    const Outcome = union(enum) {
        local,
        unknown,
        resolved,
        ambiguous: struct { a: []const u8, b: []const u8 },
    };

    fn restamp(inv: *ast_mod.Invocation, targets: []const []const u8, main: []const u8, set: *std.StringHashMap(void), a: std.mem.Allocator) Outcome {
        if (inv.path.segments.len == 0) return .unknown;
        const mq = inv.path.module_qualifier orelse return .unknown;
        if (!std.mem.eql(u8, mq, main)) return .unknown; // already qualified — not ours
        const seg = inv.path.segments[inv.path.segments.len - 1];
        if (has(set, main, seg, a)) return .local; // resolves locally — never shadow
        var first: ?[]const u8 = null;
        var second: ?[]const u8 = null;
        for (targets) |t| {
            if (has(set, t, seg, a)) {
                if (first == null) {
                    first = t;
                } else if (second == null) {
                    second = t;
                }
            }
        }
        if (first == null) return .unknown; // unknown in every target too
        if (second) |b| return .{ .ambiguous = .{ .a = first.?, .b = b } };
        inv.path.module_qualifier = a.dupe(u8, first.?) catch return .unknown;
        return .resolved;
    }

    // Restamp one invocation and, on ambiguity, record the KORU140 pick-wall
    // into ctx.errors — surfaced (and halted on) at the analysis boundary.
    fn resolveInv(inv: *ast_mod.Invocation, targets: []const []const u8, main: []const u8, set: *std.StringHashMap(void), a: std.mem.Allocator, errs: anytype, loc: anytype) void {
        switch (restamp(inv, targets, main, set, a)) {
            .ambiguous => |amb| {
                const seg = inv.path.segments[inv.path.segments.len - 1];
                const msg = std.fmt.allocPrint(a, "error[KORU140]: bare name '{s}' resolves against more than one opened vocabulary ('{s}' and '{s}') — qualify the call explicitly to pick one", .{ seg, amb.a, amb.b }) catch return;
                errs.append(a, .{ .message = msg, .location = .{
                    .file = loc.file,
                    .line = @intCast(loc.line),
                    .column = @intCast(loc.column),
                } }) catch {};
            },
            else => {},
        }
    }

    fn walkNode(node: *ast_mod.Node, targets: []const []const u8, main: []const u8, set: *std.StringHashMap(void), a: std.mem.Allocator, errs: anytype, loc: anytype) void {
        switch (node.*) {
            .invocation => |*inv| resolveInv(@constCast(inv), targets, main, set, a, errs, loc),
            .label_with_invocation => |*lwi| resolveInv(@constCast(&lwi.invocation), targets, main, set, a, errs, loc),
            .conditional_block => |*cb| {
                for (cb.nodes) |*n| walkNode(@constCast(n), targets, main, set, a, errs, loc);
            },
            .foreach => |*fe| {
                for (fe.branches) |*b| {
                    for (b.body) |*c| walkCont(@constCast(c), targets, main, set, a, errs, loc);
                }
            },
            .conditional => |*cond| {
                for (cond.branches) |*b| {
                    for (b.body) |*c| walkCont(@constCast(c), targets, main, set, a, errs, loc);
                }
            },
            .switch_result => |*sr| {
                for (sr.branches) |*b| {
                    for (b.body) |*c| walkCont(@constCast(c), targets, main, set, a, errs, loc);
                }
            },
            else => {},
        }
    }

    fn walkCont(cont: *ast_mod.Continuation, targets: []const []const u8, main: []const u8, set: *std.StringHashMap(void), a: std.mem.Allocator, errs: anytype, loc: anytype) void {
        if (cont.node) |*n| walkNode(@constCast(n), targets, main, set, a, errs, loc);
        for (cont.continuations) |*nested| walkCont(@constCast(nested), targets, main, set, a, errs, loc);
    }
};

var set = std.StringHashMap(void).init(alloc);
S.collect(ctx.original_ast.items, &set, alloc);

for (updated_ctx.ast.items) |*item| {
    if (item.* != .flow) continue;
    const flow: *const ast_mod.Flow = &item.flow;

    // Collect the vocabularies this flow opens: a flow-head `[with]` (the
    // annotation may live on the flow itself) plus every mid-chain opener.
    var targets = std.ArrayList([]const u8){};
    var seen = std.StringHashMap(void).init(alloc);
    for (flow.annotations) |ann| {
        if (std.mem.eql(u8, ann, "with")) {
            S.addTarget(flow.inv().path.module_qualifier, &targets, &seen, alloc);
        }
    }
    S.gatherCont(&flow.body, &targets, &seen, alloc);
    if (targets.items.len == 0) continue;

    S.walkCont(@constCast(&flow.body), targets.items, main_mod, &set, alloc, &updated_ctx.errors, flow.location);
}

updated_ctx.passes_completed += 1;
updated_ctx.current_pass = "resolve_with_scopes";
return updated_ctx;

const comptime_eval = @import("comptime_eval");
var folder = comptime_eval.Folder.init(ctx.allocator);
// THE THUNK LAW: hand the walker the Stage A-generated dispatch table so
// interpreted comptime Koru can call the natively-compiled handlers.
// Same @hasDecl pattern as the comptime_main call — the table only
// exists when the user program has thunkable comptime events.
const backend_output = @import("backend_output_emitted.zig");
if (@hasDecl(backend_output, "koru_comptime_thunks")) {
    folder.setThunks(&backend_output.koru_comptime_thunks);
}
const folded = folder.fold(ctx.ast) catch {
    log.err("comptime fold failed: {s}\n", .{folder.diag()});
    @panic("comptime evaluation failed — see the diagnostic above");
};

var updated_ctx = ctx;
updated_ctx.ast = folded;
updated_ctx.passes_completed += 1;
updated_ctx.current_pass = "fold_comptime";
return updated_ctx;

// Build tap registry from AST (before transformation removes taps)
const tap_registry_module = @import("tap_registry");
const registry_ptr = ctx.allocator.create(tap_registry_module.TapRegistry) catch unreachable;
registry_ptr.* = tap_registry_module.buildTapRegistry(
    ctx.ast.items,
    ctx.allocator
) catch unreachable;
// Don't defer deinit - we need the registry to persist for emission

// Transform AST - insert tap invocations as regular flow code
const tap_transformer = @import("tap_transformer");
const emitter_helpers = @import("emitter_helpers");
const transformed_ast = tap_transformer.transformAst(
    ctx.ast,
    registry_ptr,
    emitter_helpers.EmitMode.runtime_only,
    ctx.allocator
) catch unreachable;

// Update context with transformed AST and tap registry
var updated_ctx = ctx;
updated_ctx.ast = transformed_ast;
updated_ctx.tap_registry = registry_ptr;
updated_ctx.passes_completed += 1;
updated_ctx.current_pass = "transform_taps";

return updated_ctx;

var mutable_ctx = ctx;
mutable_ctx.current_pass = "test_generation";

// Import needed modules
const ast_mod = @import("ast");

// Storage for test items we'll generate
var test_inline_codes = std.ArrayList(ast_mod.Item).initCapacity(mutable_ctx.allocator, 8) catch unreachable;
var test_flows_to_remove = std.ArrayList(*const ast_mod.Flow).initCapacity(mutable_ctx.allocator, 8) catch unreachable;

// Scan AST for test invocations
// A test invocation is a flow that calls the "test" event from std.testing
for (mutable_ctx.ast.items) |item| {
    if (item == .flow) {
        const flow = &item.flow;
        // Check if this is a test invocation
        if (isTestInvocation(flow.inv())) {
            // Found a test! Process it
            const inline_code = processTestFlow(flow, mutable_ctx.ast, mutable_ctx.allocator);
            if (inline_code) |code| {
                test_inline_codes.append(mutable_ctx.allocator, code) catch {};
                test_flows_to_remove.append(mutable_ctx.allocator, flow) catch {};
            }
        }
    }
    // Also check inside modules
    if (item == .module_decl) {
        const mod = item.module_decl;
        for (mod.items) |mod_item| {
            if (mod_item == .flow) {
                const flow = &mod_item.flow;
                if (isTestInvocation(flow.inv())) {
                    const inline_code = processTestFlow(flow, mutable_ctx.ast, mutable_ctx.allocator);
                    if (inline_code) |code| {
                        test_inline_codes.append(mutable_ctx.allocator, code) catch {};
                        test_flows_to_remove.append(mutable_ctx.allocator, flow) catch {};
                    }
                }
            }
        }
    }
}

// If we found tests, build new AST with them replaced
if (test_flows_to_remove.items.len > 0) {
    log.verbose("[TEST-GEN] Found {} test(s) to generate\n", .{test_flows_to_remove.items.len});

    // Build new items array with test flows replaced by inline_codes
    var new_items = std.ArrayList(ast_mod.Item).initCapacity(mutable_ctx.allocator, mutable_ctx.ast.items.len) catch unreachable;
    var test_idx: usize = 0;

    for (mutable_ctx.ast.items) |item| {
        if (item == .flow) {
            const flow = &item.flow;
            // Check if this flow should be replaced
            var should_replace = false;
            for (test_flows_to_remove.items) |test_flow| {
                if (test_flow == flow) {
                    should_replace = true;
                    break;
                }
            }
            if (should_replace) {
                // Add the generated inline_code instead
                if (test_idx < test_inline_codes.items.len) {
                    new_items.append(mutable_ctx.allocator, test_inline_codes.items[test_idx]) catch {};
                    test_idx += 1;
                }
            } else {
                new_items.append(mutable_ctx.allocator, item) catch {};
            }
        } else {
            new_items.append(mutable_ctx.allocator, item) catch {};
        }
    }

    // Create new Program with updated items
    const new_program = mutable_ctx.allocator.create(ast_mod.Program) catch unreachable;
    new_program.* = ast_mod.Program{
        .items = new_items.items,
        .module_annotations = mutable_ctx.ast.module_annotations,
        .main_module_name = mutable_ctx.ast.main_module_name,
        .allocator = mutable_ctx.allocator,
    };
    mutable_ctx.ast = new_program;
}

mutable_ctx.passes_completed += 1;
return mutable_ctx;

// NEW VISITOR-BASED IMPLEMENTATION!
// Replaces the 2184-line procedural emitter with visitor orchestrator

// DUMP POINT 5: AST at emission entry (after all passes)
const backend_output = @import("backend_output_emitted.zig");
backend_output.dumpAST(ctx.ast, "5-emit-zig", ctx.allocator);

// Import libraries needed for emission
const emitter_lib = @import("emitter_helpers");
const visitor_emitter_lib = @import("visitor_emitter");
const tap_registry_module = @import("tap_registry");

// Growable emitter: generated code has no natural size ceiling (a large
// regex DFA alone can pass a fixed 256KB — pinned by 640_004). The buffer
// is heap-allocated (we return a slice into it via getOutput) and grows
// on demand; reads go through code_emitter.buffer, never a stale local.
var code_emitter = emitter_lib.CodeEmitter.initGrowable(ctx.allocator, 256 * 1024) catch unreachable;

// Use tap registry from context (built during transform_taps pass)
// If no registry exists, build one from current AST (shouldn't happen in normal flow)
const tap_registry = if (ctx.tap_registry) |registry|
    registry
else blk: {
    const registry_ptr = ctx.allocator.create(tap_registry_module.TapRegistry) catch unreachable;
    registry_ptr.* = tap_registry_module.buildTapRegistry(
        ctx.ast.items,
        ctx.allocator
    ) catch unreachable;
    break :blk registry_ptr;
};

// Build type registry from ORIGINAL canonicalized AST (before filtering)
// The original_ast contains ALL events (including comptime ones) so TypeRegistry has complete metadata
const type_registry_module = @import("type_registry");
var type_registry = type_registry_module.TypeRegistry.init(ctx.allocator);
defer type_registry.deinit();
type_registry.populateFromAST(ctx.original_ast.items) catch unreachable;

// Create visitor orchestrator with tap registry and type registry
// Use .runtime_only mode to emit only modules WITHOUT [comptime] annotation
var visitor_emitter = visitor_emitter_lib.VisitorEmitter.init(
    ctx.allocator,
    &code_emitter,
    ctx.ast.items,
    tap_registry,
    &type_registry,
    .runtime_only
);

// Emit using visitor pattern!
visitor_emitter.emit(ctx.ast) catch unreachable;

// Get the emitted code
const visitor_code = code_emitter.getOutput();

// JS-target spike: when --lang=js, replace the visitor's Zig output with the
// real AST→JS emitter (src/js_emitter.zig). It walks ctx.ast and emits
// runnable JavaScript for the event-pump subset (events, |js proc bodies,
// effect handlers, terminal branches, flows). Gated behind CompilerEnv.lang
// so the default Zig path is untouched. CompilerEnv is already in scope at
// file level in the generated backend_output_emitted.zig (re-exported pub
// const) — reference it directly rather than re-importing, which would
// shadow that declaration.
const final_code = if (@import("std").mem.eql(u8, CompilerEnv.lang, "js")) blk: {
    const js_emitter = @import("js_emitter");
    // Fail loud: a JS-emit failure must surface, not silently fall back to Zig.
    break :blk js_emitter.emit(ctx.allocator, ctx.ast) catch |err| {
        std.debug.panic("js_emitter.emit failed: {s}", .{@errorName(err)});
    };
} else visitor_code;

var updated_ctx = ctx;
updated_ctx.passes_completed += 1;
updated_ctx.current_pass = "emission";
return .{ .ctx = updated_ctx, .code = final_code };

const Parser = @import("parser").Parser;
// Note: 'std' is already imported at top level by the emitter

// Use a comptime-friendly allocator
// Note: In actual comptime context, we'd use a fixed buffer allocator
// For now, we use the standard allocator which works at comptime
var buffer: [1024 * 1024]u8 = undefined; // 1MB buffer for parsing
var fba = std.heap.FixedBufferAllocator.init(&buffer);
const allocator = fba.allocator();

// Initialize parser (empty compiler flags, no resolver for standalone parsing)
var parser = Parser.init(allocator, source, module_name, &[_][]const u8{}, null) catch {
    return .{ .failed = "Failed to initialize parser" };
};
defer parser.deinit();

// Parse the source
const parse_result = parser.parse() catch {
    // Try to get error details if available
    if (parser.reporter.hasErrors()) {
        return .{ .failed = "Parse error - see compiler output" };
    }
    return .{ .failed = "Failed to parse source" };
};

// Return the parsed items
// Note: The items are allocated in our buffer, which is stack-allocated
// This is fine for comptime usage where everything gets evaluated away
return .{ .parsed = parse_result.source_file.items };

const isProgramType = struct {
    fn check(raw_type: []const u8) bool {
        var t = raw_type;
        while (true) {
            t = std.mem.trimLeft(u8, t, " \t");
            if (std.mem.startsWith(u8, t, "*")) {
                t = t[1..];
                continue;
            }
            if (std.mem.startsWith(u8, t, "const")) {
                t = t["const".len..];
                continue;
            }
            break;
        }

        return std.mem.endsWith(u8, t, "Program");
    }
}.check;

// Phase 1: Build map of comptime-only events
// (Events that have Program or Source parameters)
var comptime_events: [64][]const u8 = undefined;
var comptime_count: usize = 0;

for (ctx.ast.items) |item| {
    switch (item) {
        .event_decl => |event_decl| {
            // Check if this event has comptime-only parameters
            var is_comptime = false;
            for (event_decl.input.fields) |field| {
                if (field.is_source or isProgramType(field.type)) {
                    is_comptime = true;
                    break;
                }
            }

            if (is_comptime and comptime_count < 64) {
                // Build event name from path segments using heap allocation
                const path_str = joinPathAlloc(ctx.allocator, event_decl.path.segments);
                const event_name = if (event_decl.path.module_qualifier) |mq|
                    std.fmt.allocPrint(ctx.allocator, "{s}:{s}", .{mq, path_str}) catch path_str
                else
                    path_str;
                comptime_events[comptime_count] = event_name;
                comptime_count += 1;
            }
        },
        .module_decl => |module| {
            // Also check imported modules
            for (module.items) |mod_item| {
                if (mod_item == .event_decl) {
                    const event_decl = mod_item.event_decl;
                    var is_comptime = false;
                    for (event_decl.input.fields) |field| {
                        if (field.is_source or isProgramType(field.type)) {
                            is_comptime = true;
                            break;
                        }
                    }

                    if (is_comptime and comptime_count < 64) {
                        // For module events, include the module name: "std.build:requires"
                        const path_str = joinPathAlloc(ctx.allocator, event_decl.path.segments);
                        const event_name = if (module.logical_name.len > 0)
                            std.fmt.allocPrint(ctx.allocator, "{s}:{s}", .{module.logical_name, path_str}) catch path_str
                        else
                            path_str;
                        comptime_events[comptime_count] = event_name;
                        comptime_count += 1;
                    }
                }
            }
        },
        else => {},
    }
}

// Phase 2: Walk flows and find comptime event invocations
// std.debug.print("  Phase 2: Scanning flows for comptime invocations...\n", .{});
for (ctx.ast.items) |item| {
    if (item == .flow) {
        const flow = item.flow;
        // For module-qualified flows, include the module name: "std.build:requires"
        const path_str = joinPathAlloc(ctx.allocator, flow.inv().path.segments);
        const inv_path = if (flow.inv().path.module_qualifier) |mq|
            std.fmt.allocPrint(ctx.allocator, "{s}:{s}", .{mq, path_str}) catch path_str
        else
            path_str;
        // std.debug.print("    Flow invokes: {s}\n", .{inv_path});

        // Check if this invocation is to a comptime event
        for (0..comptime_count) |i| {
            if (std.mem.eql(u8, inv_path, comptime_events[i])) {
                // Found a comptime event invocation!
                // std.debug.print("  ✓ Found comptime invocation: {s}\n", .{inv_path});

                // TODO: Call the comptime handler!
                // const handler_result = callComptimeHandler(inv_path, ctx.ast);
                // For now, just print that we called it
                // TODO: Use result to transform flow/AST
                // switch (handler_result) {
                //     .none => {
                //         // std.debug.print("  WARNING: Handler not found for: {s}\n", .{inv_path});
                //     },
                // }

                break;
            }
        }
    }
}

// std.debug.print("  Detected {} comptime events, {} invocations\n", .{comptime_count, invocations_found});

const backend_output = @import("backend_output_emitted.zig");

// Phase 2.3.5: Early comptime_main pass — registers build-time configuration
// (build:variants, build:config) into emitter_helpers registries so that Phase 2.4
// transforms can dispatch through the populated registry. Phase 2.5 runs
// comptime_main again for post-transform work (tap injection etc.). This
// double-execution is a known wart; the cleaner fix is to segregate
// build-config flows into a dedicated pre_transform_main() at codegen time.
if (@hasDecl(backend_output, "comptime_main")) {
    log.debug("[PHASE 2.3.5] Early comptime_main() — registering build-time variants/config\n", .{});
    _ = backend_output.comptime_main(ctx.ast, ctx.allocator);
}

// Phase 2.4: Execute transform handlers FIRST (if they exist)
// NOTE: Transforms run BEFORE comptime events so that comptime events
// (like tap injection) can see the fully-transformed AST
const transform_updated_ctx = if (@hasDecl(backend_output, "run_pass")) blk: {
    log.debug("[PHASE 2.4] Calling run_pass for transforms\\n", .{});

    // DUMP POINT 3: AST before transform handlers
    backend_output.dumpAST(ctx.ast, "3-pre-transform", ctx.allocator);

    const post_transform_ast = backend_output.run_pass("transform", ctx.ast, ctx.allocator) catch |err| {
        // Transforms either complete or fail loudly. Continuing with the
        // untransformed AST used to mask the failure behind a cascade of
        // downstream KORU021/022 errors about events the transform should
        // have rewritten away.
        log.err("FATAL: transform pass failed ({s}). The pipeline cannot continue with a partially-transformed AST.\n", .{@errorName(err)});
        @panic("transform pass failed — see error above");
    };

    // DUMP POINT 4: AST after transform handlers
    backend_output.dumpAST(post_transform_ast, "4-post-transform", ctx.allocator);

    var transform_ctx = ctx;
    transform_ctx.ast = post_transform_ast;
    break :blk transform_ctx;
} else ctx;

// Phase 2.5: Execute comptime flows AFTER transforms (if they exist)
// comptime_main() calls all comptime_flowN() functions at Zig RUNTIME (when ./backend runs)
// Now sees the transformed AST, enabling comptime events to do post-transform work
// Returns *const Program — comptime flows may modify the AST
const comptime_updated_ctx = if (@hasDecl(backend_output, "comptime_main")) blk: {
    log.debug("[PHASE 2.5] Executing comptime_main() - running comptime flows\n", .{});
    const post_comptime_ast = backend_output.comptime_main(transform_updated_ctx.ast, transform_updated_ctx.allocator);
    log.debug("[PHASE 2.5] Comptime flows complete ({} items)\n", .{post_comptime_ast.items.len});
    var comptime_ctx = transform_updated_ctx;
    comptime_ctx.ast = post_comptime_ast;
    break :blk comptime_ctx;
} else transform_updated_ctx;

// Phase 2.6: Rebuild comptime_events list from transformed AST
// Transforms may have added/removed events, so we need to rescan
log.debug("[PHASE 2.6] Rescanning transformed AST ({} items)\n", .{comptime_updated_ctx.ast.items.len});
comptime_count = 0;  // Reset counter
for (comptime_updated_ctx.ast.items) |item| {
    switch (item) {
        .event_decl => |event_decl| {
            // Check if this event has comptime-only parameters
            var is_comptime = false;
            for (event_decl.input.fields) |field| {
                if (field.is_source or isProgramType(field.type)) {
                    is_comptime = true;
                    break;
                }
            }

            if (is_comptime and comptime_count < 64) {
                // Use heap-allocated path string
                const path_str = joinPathAlloc(ctx.allocator, event_decl.path.segments);
                const event_name = if (event_decl.path.module_qualifier) |mq|
                    std.fmt.allocPrint(ctx.allocator, "{s}:{s}", .{mq, path_str}) catch path_str
                else
                    path_str;
                log.debug("  Found comptime event: {s} (fields: {})\n", .{event_name, event_decl.input.fields.len});
                comptime_events[comptime_count] = event_name;
                comptime_count += 1;
            }
        },
        .module_decl => |module| {
            for (module.items) |mod_item| {
                if (mod_item == .event_decl) {
                    const event_decl = mod_item.event_decl;
                    var is_comptime = false;
                    for (event_decl.input.fields) |field| {
                        if (field.is_source or isProgramType(field.type)) {
                            is_comptime = true;
                            break;
                        }
                    }

                    if (is_comptime and comptime_count < 64) {
                        const path_str = joinPathAlloc(ctx.allocator, event_decl.path.segments);
                        const event_name = if (module.logical_name.len > 0)
                            std.fmt.allocPrint(ctx.allocator, "{s}:{s}", .{module.logical_name, path_str}) catch path_str
                        else
                            path_str;
                        comptime_events[comptime_count] = event_name;
                        comptime_count += 1;
                    }
                }
            }
        },
        else => {},
    }
}
log.debug("[PHASE 2.6] Rescan complete: {} comptime events found\n", .{comptime_count});
for (0..comptime_count) |i| {
    log.debug("  [{}] {s}\n", .{i, comptime_events[i]});
}

// Phase 3: Build new AST without comptime flows, procs, and modules (AST TRANSFORMATION!)
// Count non-comptime items first
var count_non_comptime: usize = 0;
for (comptime_updated_ctx.ast.items) |item| {
    var should_keep = true;
    if (item == .flow) {
        const flow = item.flow;
        // For module-qualified flows, include the module name: "std.build:requires"
        const path_str = joinPathAlloc(ctx.allocator, flow.inv().path.segments);
        const inv_path = if (flow.inv().path.module_qualifier) |mq|
            std.fmt.allocPrint(ctx.allocator, "{s}:{s}", .{mq, path_str}) catch path_str
        else
            path_str;

        // Check if comptime flow
        for (0..comptime_count) |i| {
            if (std.mem.eql(u8, inv_path, comptime_events[i])) {
                var transformed = false;
                if (flow.inline_body != null or flow.preamble_code != null) {
                    transformed = true;
                } else {
                    for (flow.inv().annotations) |ann| {
                        if (std.mem.eql(u8, ann, "@pass_ran(\"transform\")")) {
                            transformed = true;
                            break;
                        }
                    }
                }
                if (!transformed) {
                    should_keep = false;
                }
                break;
            }
        }
    }

    // Filter out comptime procs (they were already executed)
    // Note: [raw] annotation only affects emission style, not filtering
    if (item == .proc_decl) {
        const proc = item.proc_decl;

        // Check if this proc is comptime (in comptime_events list)
        const proc_path_str = joinPathAlloc(ctx.allocator, proc.path.segments);
        const proc_path = if (proc.path.module_qualifier) |mq|
            std.fmt.allocPrint(ctx.allocator, "{s}:{s}", .{mq, proc_path_str}) catch proc_path_str
        else
            proc_path_str;
        for (0..comptime_count) |i| {
            if (std.mem.eql(u8, proc_path, comptime_events[i])) {
                // This is a comptime proc - filter it out (already executed)
                should_keep = false;
                break;
            }
        }
    }

    // NOTE: Don't filter modules based on [comptime] annotation here.
    // Modules with [comptime] may contain [runtime] events that need to be emitted.
    // The visitor_emitter handles this correctly by checking if the module contains
    // any emittable items before filtering the module itself.

    if (should_keep) {
        count_non_comptime += 1;
    }
}

// Build new array with exact size (now allocated at runtime)
const new_items = ctx.allocator.alloc(Item, count_non_comptime) catch {
    // Allocation failed - return original AST unchanged
    return ctx;
};
var idx: usize = 0;
for (comptime_updated_ctx.ast.items) |item| {
    var should_keep = true;
    if (item == .flow) {
        const flow = item.flow;
        // For module-qualified flows, include the module name: "std.build:requires"
        const path_str2 = joinPathAlloc(ctx.allocator, flow.inv().path.segments);
        const inv_path = if (flow.inv().path.module_qualifier) |mq|
            std.fmt.allocPrint(ctx.allocator, "{s}:{s}", .{mq, path_str2}) catch path_str2
        else
            path_str2;

        // Check if comptime flow
        for (0..comptime_count) |i| {
            if (std.mem.eql(u8, inv_path, comptime_events[i])) {
                var transformed = false;
                if (flow.inline_body != null or flow.preamble_code != null) {
                    transformed = true;
                } else {
                    for (flow.inv().annotations) |ann| {
                        if (std.mem.eql(u8, ann, "@pass_ran(\"transform\")")) {
                            transformed = true;
                            break;
                        }
                    }
                }
                if (!transformed) {
                    should_keep = false;
                }
                break;
            }
        }
    }

    // Filter out comptime procs (they were already executed)
    // Note: [raw] annotation only affects emission style, not filtering
    if (item == .proc_decl) {
        const proc = item.proc_decl;

        // Check if this proc is comptime (in comptime_events list)
        const proc_path_str = joinPathAlloc(ctx.allocator, proc.path.segments);
        const proc_path = if (proc.path.module_qualifier) |mq|
            std.fmt.allocPrint(ctx.allocator, "{s}:{s}", .{mq, proc_path_str}) catch proc_path_str
        else
            proc_path_str;
        for (0..comptime_count) |i| {
            if (std.mem.eql(u8, proc_path, comptime_events[i])) {
                // This is a comptime proc - filter it out (already executed)
                should_keep = false;
                break;
            }
        }
    }

    // NOTE: Don't filter modules based on [comptime] annotation here.
    // Modules with [comptime] may contain [runtime] events that need to be emitted.
    // The visitor_emitter handles this correctly by checking if the module contains
    // any emittable items before filtering the module itself.

    if (should_keep) {
        new_items[idx] = item;
        idx += 1;
    }
}

const transformed_ast = ctx.allocator.create(Program) catch {
    // Allocation failed - return original AST unchanged
    return ctx;
};
transformed_ast.* = Program{
    .items = new_items,
    .module_annotations = ctx.ast.module_annotations,
    .main_module_name = ctx.ast.main_module_name,
    .allocator = ctx.allocator,
};

// Update context with transformed AST
// IMPORTANT: Keep original_ast unchanged - it preserves comptime event metadata!
var updated_ctx = ctx;
updated_ctx.ast = transformed_ast;  // Filtered AST for emission
// updated_ctx.original_ast stays the same - unfiltered AST for TypeRegistry
updated_ctx.passes_completed += 1;
updated_ctx.current_pass = "evaluate_comptime";

return updated_ctx;

var mutable_ctx = ctx;
mutable_ctx.current_pass = "check_release_gate";

// Only release builds gate. Dev builds allow ~[prototype].
if (!CompilerEnv.hasFlag("release")) {
    return .{ .ctx = mutable_ctx };
}

const release_gate = @import("release_gate");
const errors_mod = @import("errors");

var reporter = errors_mod.ErrorReporter.init(
    std.heap.page_allocator,
    "release_gate",
    ""
) catch {
    mutable_ctx.errors.append(mutable_ctx.allocator, .{
        .message = "Failed to initialize error reporter",
        .location = .{ .file = "compiler", .line = 0, .column = 0 },
    }) catch {};
    return .{ .ctx = mutable_ctx };
};
defer reporter.deinit();

var gate = release_gate.ReleaseGate.init(&reporter);
gate.check(mutable_ctx.ast) catch |err| {
    for (reporter.errors.items) |reporter_err| {
        std.debug.print("error[{s}]: {s}\n  --> {s}:{}:{}\n\n", .{
            @tagName(reporter_err.code),
            reporter_err.message,
            reporter_err.location.file,
            reporter_err.location.line,
            reporter_err.location.column,
        });

        mutable_ctx.errors.append(mutable_ctx.allocator, .{
            .message = mutable_ctx.allocator.dupe(u8, reporter_err.message) catch reporter_err.message,
            .location = .{
                .file = mutable_ctx.allocator.dupe(u8, reporter_err.location.file) catch reporter_err.location.file,
                .line = @intCast(reporter_err.location.line),
                .column = @intCast(reporter_err.location.column),
            },
        }) catch {};
    }

    const err_msg = switch (err) {
        error.ReleaseRejectsPrototype => "prototype module rejected in release build",
        else => "release gate error",
    };

    return .{ .failed = .{ .ctx = mutable_ctx, .message = err_msg } };
};

mutable_ctx.passes_completed += 1;
return .{ .ctx = mutable_ctx };

// Need mutable ctx to append errors
var mutable_ctx = ctx;
mutable_ctx.current_pass = "check_structure";

// Surface any diagnostics a FRONTEND pass already recorded (name resolution
// has no `.failed` arm of its own — `resolve-with-scopes` reports the KORU140
// `[with]` pick-wall into ctx.errors, and analysis is the first boundary that
// can halt cleanly). Print and fail BEFORE structural checking, so the real
// diagnostic wins instead of a downstream "unknown event" for the name the
// frontend deliberately left unresolved.
if (mutable_ctx.errors.items.len > 0) {
    for (mutable_ctx.errors.items) |e| {
        std.debug.print("{s}\n  --> {s}:{}:{}\n\n", .{
            e.message,
            e.location.file,
            e.location.line,
            e.location.column,
        });
    }
    return .{ .failed = .{ .ctx = mutable_ctx, .message = mutable_ctx.errors.items[0].message } };
}

// Use the Zig shape_checker library for structural validation
const shape_checker = @import("shape_checker");
const errors_mod = @import("errors");

// Create error reporter
var reporter = errors_mod.ErrorReporter.init(
    std.heap.page_allocator,
    "structural_check",
    ""
) catch {
    // Report error to context
    mutable_ctx.errors.append(mutable_ctx.allocator, .{
        .message = "Failed to initialize error reporter",
        .location = .{ .file = "compiler", .line = 0, .column = 0 },
    }) catch {};
    return .{ .ctx = mutable_ctx };
};
defer reporter.deinit();

// Create shape checker
var checker = shape_checker.ShapeChecker.init(
    std.heap.page_allocator,
    &reporter
) catch {
    // Report error to context
    mutable_ctx.errors.append(mutable_ctx.allocator, .{
        .message = "Failed to initialize shape checker",
        .location = .{ .file = "compiler", .line = 0, .column = 0 },
    }) catch {};
    return .{ .ctx = mutable_ctx };
};
defer checker.deinit();

// ~[prototype]: relax required terminal-branch exhaustiveness so unhandled
// `|` branches become synthesized @panic holes (see ShapeChecker.prototype_mode).
for (mutable_ctx.ast.module_annotations) |ann| {
    if (std.mem.eql(u8, ann, "prototype")) {
        checker.prototype_mode = true;
    }
}

// Run structural validation
checker.checkSourceFile(mutable_ctx.ast) catch |err| {
    // Print all errors from the reporter for visibility
    for (reporter.errors.items) |reporter_err| {
        std.debug.print("error[{s}]: {s}\n  --> {s}:{}:{}\n\n", .{
            @tagName(reporter_err.code),
            reporter_err.message,
            reporter_err.location.file,
            reporter_err.location.line,
            reporter_err.location.column,
        });

        mutable_ctx.errors.append(mutable_ctx.allocator, .{
            .message = mutable_ctx.allocator.dupe(u8, reporter_err.message) catch reporter_err.message,
            .location = .{
                .file = mutable_ctx.allocator.dupe(u8, reporter_err.location.file) catch reporter_err.location.file,
                .line = @intCast(reporter_err.location.line),
                .column = @intCast(reporter_err.location.column),
            },
        }) catch {};
    }

    // Generate error message based on error type
    const err_msg = switch (err) {
        error.UnknownEvent => "Unknown event referenced",
        error.IncompleteBranchCoverage => "Incomplete branch coverage",
        error.ProcWithoutEvent => "Proc without matching event",
        error.SubflowWithoutEvent => "Subflow without matching event",
        error.DuplicateBranchHandler => "Duplicate branch handler at same indentation level",
        error.ValidationFailed => "Validation failed (see errors above)",
        error.InvalidPath => "Invalid path",
        error.DuplicateLabel => "Duplicate label defined",
        error.UnknownLabel => "Unknown label referenced",
        error.DeprecatedInlineFlowPath => "Deprecated inline flow path",
        error.LabelRequiresParameters => "Label requires parameters",
        error.LabelDoesNotAcceptParameters => "Label does not accept parameters",
        error.InvalidBranchConstructor => "Invalid branch constructor",
        else => "Structural validation failed (unknown error)",
    };

    // Return failed branch - stops the pipeline!
    return .{ .failed = .{ .ctx = mutable_ctx, .message = err_msg } };
};

// Validation succeeded
mutable_ctx.passes_completed += 1;
return .{ .ctx = mutable_ctx };

// Need mutable ctx to append errors
var mutable_ctx = ctx;
mutable_ctx.current_pass = "check_flow";

// Use the Zig flow_checker library for flow validation
const flow_checker = @import("flow_checker");
const errors_mod = @import("errors");

// Create error reporter
var reporter = errors_mod.ErrorReporter.init(
    std.heap.page_allocator,
    "flow_check",
    ""
) catch {
    // Report error to context
    mutable_ctx.errors.append(mutable_ctx.allocator, .{
        .message = "Failed to initialize error reporter",
        .location = .{ .file = "compiler", .line = 0, .column = 0 },
    }) catch {};
    return .{ .ctx = mutable_ctx };
};
defer reporter.deinit();

// Create flow checker
var checker = flow_checker.FlowChecker.init(
    std.heap.page_allocator,
    &reporter
) catch {
    // Report error to context
    mutable_ctx.errors.append(mutable_ctx.allocator, .{
        .message = "Failed to initialize flow checker",
        .location = .{ .file = "compiler", .line = 0, .column = 0 },
    }) catch {};
    return .{ .ctx = mutable_ctx };
};
defer checker.deinit();

// ~[prototype]: relax required terminal-branch exhaustiveness (see
// FlowChecker.prototype_mode). Consistent with check-structure; by this pass
// the auto-discharge synthesis has usually already filled the hole arm.
for (mutable_ctx.ast.module_annotations) |ann| {
    if (std.mem.eql(u8, ann, "prototype")) {
        checker.prototype_mode = true;
    }
}

// Run flow validation
checker.checkSourceFile(mutable_ctx.ast) catch |err| {
    // Print all errors from the reporter for visibility
    for (reporter.errors.items) |reporter_err| {
        std.debug.print("error[{s}]: {s}\n  --> {s}:{}:{}\n\n", .{
            @tagName(reporter_err.code),
            reporter_err.message,
            reporter_err.location.file,
            reporter_err.location.line,
            reporter_err.location.column,
        });

        mutable_ctx.errors.append(mutable_ctx.allocator, .{
            .message = mutable_ctx.allocator.dupe(u8, reporter_err.message) catch reporter_err.message,
            .location = .{
                .file = mutable_ctx.allocator.dupe(u8, reporter_err.location.file) catch reporter_err.location.file,
                .line = @intCast(reporter_err.location.line),
                .column = @intCast(reporter_err.location.column),
            },
        }) catch {};
    }

    // Generate error message based on error type
    const err_msg = switch (err) {
        error.FlowValidationFailed => "Flow validation failed",
        error.DuplicateBranchHandler => "Duplicate branch handler at same indentation level",
        else => "Flow validation error",
    };

    // Return failed branch - stops the pipeline!
    return .{ .failed = .{ .ctx = mutable_ctx, .message = err_msg } };
};

// Validation succeeded
mutable_ctx.passes_completed += 1;
return .{ .ctx = mutable_ctx };

// Check if auto-discharge is disabled entirely. Disabling means "do not
// INSERT disposal calls — let phantom errors fire"; it never means the
// discard shapes go invisible. The pass still runs in normalize-only mode
// below so an obligation-carrying bare call (`~open()` discarding a
// `-> T<state!>` return) is materialized into its explicit `: _ |> _`
// form and the phantom checker can fire KORU030 on the leak.
const insertion_disabled = CompilerEnv.hasFlag("auto-discharge=disable");

// Honor the `strict` module-level convention.
// `strict` is an opaque annotation word, not a fixed semantics: each pass
// that cares reads it and renders it into its own domain. For auto-discharge,
// strict means "do not guess the single cleanup — require it explicitly",
// so a module marked ~[strict] opts out of insertion and the phantom checker
// fires KORU030 for any undischarged obligation. Other passes (ours and
// third-party) may read the same word and honor it in their own lane.
var strict_module = false;
for (ctx.ast.module_annotations) |ann| {
    if (std.mem.eql(u8, ann, "strict")) {
        strict_module = true;
    }
}

// Check if warnings are enabled for auto-discharge
const warn_mode = CompilerEnv.hasFlag("auto-discharge=warn");

// Crash-surface map (strict mode): --panic-branches=strict makes every
// unhandled panic branch (| ?!...) a compile error (KORU022), enumerating
// where the program can crash on a rare failure. Dev build (flag off) stays
// silent — the synthesized @panic is still there at runtime; production/audit
// build (flag on) blocks compilation until each is handled or explicitly
// muted (`| <name> _ |> ...`). Same source, flag flips it.
const strict_panic_branches = CompilerEnv.hasFlag("panic-branches=strict");

// `~[prototype]`: module opt-in to compile-and-run INCOMPLETE. An unhandled
// required TERMINAL branch becomes a synthesized @panic hole (same body as
// an unhandled `| ?!`) instead of a KORU022 exhaustiveness error — so a
// half-shaped program runs its built paths now and crashes loudly at a hole.
// Read like `strict` (an opaque module-annotation word), but it does NOT
// early-return: the pass runs WITH the flag so synthesis fills the holes.
// Never leaks to production — without the annotation this stays false and
// exhaustiveness is enforced.
var prototype_mode = false;
for (ctx.ast.module_annotations) |ann| {
    if (std.mem.eql(u8, ann, "prototype")) {
        prototype_mode = true;
    }
}

var mutable_ctx = ctx;
mutable_ctx.current_pass = "auto_discharge";

const auto_discharge_inserter = @import("auto_discharge_inserter");
const errors_mod = @import("errors");

// Create error reporter
var reporter = errors_mod.ErrorReporter.init(
    std.heap.page_allocator,
    "auto_discharge",
    ""
) catch {
    mutable_ctx.errors.append(mutable_ctx.allocator, .{
        .message = "Failed to initialize error reporter",
        .location = .{ .file = "compiler", .line = 0, .column = 0 },
    }) catch {};
    return .{ .ctx = mutable_ctx };
};
defer reporter.deinit();

// Create inserter with warn_mode flag
var inserter = auto_discharge_inserter.AutoDischargeInserter.init(
    std.heap.page_allocator,
    &reporter,
    warn_mode,
    strict_panic_branches,
    prototype_mode,
) catch {
    mutable_ctx.errors.append(mutable_ctx.allocator, .{
        .message = "Failed to initialize auto-discharge inserter",
        .location = .{ .file = "compiler", .line = 0, .column = 0 },
    }) catch {};
    return .{ .ctx = mutable_ctx };
};
defer inserter.deinit();

// Run the pass - may modify AST. Insertion opted out (flag or ~[strict])
// still normalizes head discards so downstream enforcement sees them.
const run_result = if (insertion_disabled or strict_module)
    inserter.runNormalizeOnly(mutable_ctx.ast)
else
    inserter.run(mutable_ctx.ast);
const new_ast = run_result catch |err| {
    // Collect errors from reporter into context
    for (reporter.errors.items) |reporter_err| {
        std.debug.print("error[{s}]: {s}\n  --> {s}:{}:{}\n\n", .{
            @tagName(reporter_err.code),
            reporter_err.message,
            reporter_err.location.file,
            reporter_err.location.line,
            reporter_err.location.column,
        });

        mutable_ctx.errors.append(mutable_ctx.allocator, .{
            .message = mutable_ctx.allocator.dupe(u8, reporter_err.message) catch reporter_err.message,
            .location = .{
                .file = mutable_ctx.allocator.dupe(u8, reporter_err.location.file) catch reporter_err.location.file,
                .line = @intCast(reporter_err.location.line),
                .column = @intCast(reporter_err.location.column),
            },
        }) catch {};
    }

    const err_msg = switch (err) {
        error.ValidationFailed => "Auto-discharge failed (multiple disposal options or no disposal event)",
        else => "Auto-discharge pass error",
    };

    return .{ .failed = .{ .ctx = mutable_ctx, .message = err_msg } };
};

// Update AST with potentially modified version
mutable_ctx.ast = new_ast;
mutable_ctx.passes_completed += 1;
return .{ .ctx = mutable_ctx };

log.debug("\n[PHANTOM-KORU] Starting phantom check proc...\n", .{});
// Need mutable ctx to append errors
var mutable_ctx = ctx;
mutable_ctx.current_pass = "check_phantom";

// Use the Zig phantom_semantic_checker library for phantom state validation
const phantom_semantic_checker = @import("phantom_semantic_checker");
const errors_mod = @import("errors");

// Create error reporter
var reporter = errors_mod.ErrorReporter.init(
    std.heap.page_allocator,
    "phantom_semantic_check",
    ""
) catch {
    // Report error to context
    mutable_ctx.errors.append(mutable_ctx.allocator, .{
        .message = "Failed to initialize error reporter",
        .location = .{ .file = "compiler", .line = 0, .column = 0 },
    }) catch {};
    return .{ .ctx = mutable_ctx };
};
defer reporter.deinit();

// Create phantom semantic checker
var checker = phantom_semantic_checker.PhantomSemanticChecker.init(
    std.heap.page_allocator,
    &reporter
) catch {
    // Report error to context
    mutable_ctx.errors.append(mutable_ctx.allocator, .{
        .message = "Failed to initialize phantom semantic checker",
        .location = .{ .file = "compiler", .line = 0, .column = 0 },
    }) catch {};
    return .{ .ctx = mutable_ctx };
};
defer checker.deinit();

// ~[prototype]: relax the "handled a branch the event doesn't produce" wall
// (KORU030) for terminal continuations — the doodle where handler arms lead
// the declaration (see PhantomSemanticChecker.prototype_mode, 400_165).
// Consistent with check-structure / check-flow.
for (mutable_ctx.ast.module_annotations) |ann| {
    if (std.mem.eql(u8, ann, "prototype")) {
        checker.prototype_mode = true;
    }
}

// Run phantom semantic validation
checker.check(mutable_ctx.ast) catch |err| {
    // Collect errors from reporter into context
    for (reporter.errors.items) |reporter_err| {
        // Print to stderr immediately for visibility in regression tests
        std.debug.print("error[{s}]: {s}\n  --> {s}:{}:{}\n\n", .{
            @tagName(reporter_err.code),
            reporter_err.message,
            reporter_err.location.file,
            reporter_err.location.line,
            reporter_err.location.column,
        });

        mutable_ctx.errors.append(mutable_ctx.allocator, .{
            .message = mutable_ctx.allocator.dupe(u8, reporter_err.message) catch reporter_err.message,
            .location = .{
                .file = mutable_ctx.allocator.dupe(u8, reporter_err.location.file) catch reporter_err.location.file,
                .line = @intCast(reporter_err.location.line),
                .column = @intCast(reporter_err.location.column),
            },
        }) catch {};
    }

    // Generate error message based on error type
    const err_msg = switch (err) {
        error.ValidationFailed => "Phantom semantic validation failed",
        else => "Phantom semantic validation error",
    };

    // Return failed branch - stops the pipeline!
    return .{ .failed = .{ .ctx = mutable_ctx, .message = err_msg } };
};

// Validation succeeded
mutable_ctx.passes_completed += 1;
return .{ .ctx = mutable_ctx };

var mutable_ctx = ctx;
mutable_ctx.current_pass = "check_purity";

// Purity is determined by [pure] annotation only
// We don't analyze host (Zig) code - if you say it's pure, we trust you

mutable_ctx.passes_completed += 1;
return .{ .ctx = mutable_ctx };

var mutable_ctx = ctx;
mutable_ctx.current_pass = "dead_strip";

const dead_strip = @import("dead_strip");

var pass = dead_strip.DeadStripPass.init(std.heap.page_allocator);
defer pass.deinit();

const new_ast = pass.run(mutable_ctx.ast) catch {
    return mutable_ctx;
};

mutable_ctx.ast = new_ast;
mutable_ctx.passes_completed += 1;
return mutable_ctx;

// Inject CCP observability helpers as self-contained Zig code
// Uses __ccp_std local import to avoid namespace pollution

// CCP is a self-governing feature that requires BOTH:
// 1. User imports std/ccp (declares intent to use CCP)
// 2. Compiler flag --ccp is set (enables CCP infrastructure)
// This pattern allows features to exist in AST but remain dormant without flags

// TODO: CCP feature is disabled until CompilerEnv is implemented
// This would inject observability helpers when --ccp flag is set
var updated_ctx = ctx;
updated_ctx.passes_completed += 1;
return updated_ctx;

// TODO: Check if --ccp flag is enabled via CompilerEnv
// TODO: Attempt non-blocking stdin read for JSONL commands
// TODO: Parse and dispatch commands to appropriate handlers
// For now, just pass through the context unchanged
var updated_ctx = ctx;
updated_ctx.passes_completed += 1;
return updated_ctx;

const ast = @import("ast");

if (item.* != .flow) @panic("std/parser grammar transform: containing item is not a flow - walker dispatch contract broken");
const flow = &item.flow;

if (invocation.args.len == 0) {
    const msg = std.fmt.allocPrint(allocator, "comptime {{ @compileError(\"std/parser:grammar requires a name: grammar(<name>)\"); }}", .{}) catch unreachable;
    return .{ .transformed = .{ .replacement = ast.Item{ .inline_code = ast.InlineCode{ .code = msg, .location = flow.location, .module = flow.module } } } };
}

// Validate the region: every arm is `! <rule-name> <cursor> |> <picker>`.
for (flow.body.continuations) |c| {
    if (c.kind != .effect) {
        const msg = std.fmt.allocPrint(allocator, "comptime {{ @compileError(\"std/parser:grammar rules are effect arms: `! <rule-name> <cursor> |> std/parser:match(<cursor>)`, found terminal `{s}`\"); }}", .{c.branch}) catch unreachable;
        return .{ .transformed = .{ .replacement = ast.Item{ .inline_code = ast.InlineCode{ .code = msg, .location = flow.location, .module = flow.module } } } };
    }
    if (c.binding == null) {
        const msg = std.fmt.allocPrint(allocator, "comptime {{ @compileError(\"std/parser:grammar rule `{s}` needs a cursor binding: `! {s} <cursor> |> std/parser:match(<cursor>)`\"); }}", .{ c.branch, c.branch }) catch unreachable;
        return .{ .transformed = .{ .replacement = ast.Item{ .inline_code = ast.InlineCode{ .code = msg, .location = flow.location, .module = flow.module } } } };
    }
}

// Neutralize: the region declares rules, it does not run. Keep the
// continuations (parse sites read them from the program AST) but flag the
// subtree transformed so structural checkers skip the rule arms, and make
// the emitted statement an empty block.
const new_anns = allocator.alloc([]const u8, flow.inv().annotations.len + 1) catch unreachable;
for (flow.inv().annotations, 0..) |an, k| new_anns[k] = an;
new_anns[flow.inv().annotations.len] = allocator.dupe(u8, "@pass_ran(\"transform\")") catch unreachable;

const new_inv = ast.Invocation{
    .path = flow.inv().path,
    .args = flow.inv().args,
    .annotations = new_anns,
    .inserted_by_tap = flow.inv().inserted_by_tap,
    .from_opaque_tap = flow.inv().from_opaque_tap,
};

const kept = allocator.alloc(ast.Continuation, flow.body.continuations.len) catch unreachable;
for (flow.body.continuations, 0..) |c, k| {
    kept[k] = c;
    kept[k].is_transformed_subtree = true;
}

var new_flow = flow.*;
new_flow.body = ast.rootSite(new_inv, kept, flow.location);
new_flow.inline_body = allocator.dupe(u8, "//@koru:inline_stmt\n{}") catch unreachable;

return .{ .transformed = .{ .replacement = ast.Item{ .flow = new_flow } } };

const ast = @import("ast");

// All pure helpers live in a container so they can recurse; it re-imports
// what it needs (fn-scope containers cannot reach fn-scope consts).
const H = struct {
    const std2 = @import("std");
    const ast2 = @import("ast");
    const regex = @import("regex_engine");

    const Ctx = struct {
        a: std2.mem.Allocator,
        sfx: []const u8, // site-unique suffix
        rules: []const ast2.Continuation, // the rule arms (branch = rule name)
        matchers: *std2.ArrayList(u8), // emitted top-level fns
        pats: *std2.ArrayList([]const u8), // distinct terminal patterns (index = matcher id)
        label_n: *usize, // unique Zig block labels
        fail: *?[]const u8, // first validation failure, as a @compileError body
    };

    fn zigEscape(a: std2.mem.Allocator, s: []const u8) []const u8 {
        var out = std2.ArrayList(u8){};
        for (s) |ch| {
            switch (ch) {
                '"' => out.appendSlice(a, "\\\"") catch unreachable,
                '\\' => out.appendSlice(a, "\\\\") catch unreachable,
                '\n' => out.appendSlice(a, "\\n") catch unreachable,
                '\r' => out.appendSlice(a, "\\r") catch unreachable,
                '\t' => out.appendSlice(a, "\\t") catch unreachable,
                else => out.append(a, ch) catch unreachable,
            }
        }
        return out.toOwnedSlice(a) catch unreachable;
    }

    fn sanitize(a: std2.mem.Allocator, s: []const u8) []const u8 {
        const out = a.dupe(u8, s) catch unreachable;
        for (out) |*ch| {
            if (!((ch.* >= 'a' and ch.* <= 'z') or (ch.* >= 'A' and ch.* <= 'Z') or (ch.* >= '0' and ch.* <= '9'))) ch.* = '_';
        }
        return out;
    }

    fn findRule(rules: []const ast2.Continuation, name: []const u8) ?*const ast2.Continuation {
        for (rules) |*r| {
            if (std2.mem.eql(u8, r.branch, name)) return r;
        }
        return null;
    }

    fn setFail(ctx: *const Ctx, msg: []const u8) void {
        if (ctx.fail.* == null) ctx.fail.* = msg;
    }

    /// Is this invocation `std/parser:<verb>`? Matches the path's single
    /// segment + a module qualifier ending in "parser".
    fn isVerb(inv: *const ast2.Invocation, verb: []const u8) bool {
        if (inv.path.segments.len != 1) return false;
        if (!std2.mem.eql(u8, inv.path.segments[0], verb)) return false;
        const q = inv.path.module_qualifier orelse return false;
        return std2.mem.endsWith(u8, q, "parser");
    }

    /// Strip the surrounding quotes off a string-literal arg value.
    fn stripQuotes(s: []const u8) []const u8 {
        const t = std2.mem.trim(u8, s, " \t");
        if (t.len >= 2 and t[0] == '"' and t[t.len - 1] == '"') return t[1 .. t.len - 1];
        return t;
    }

    /// Matcher id for a terminal pattern, compiling it on first sight.
    fn matcherFor(ctx: *const Ctx, pattern: []const u8) usize {
        for (ctx.pats.items, 0..) |p, i| {
            if (std2.mem.eql(u8, p, pattern)) return i;
        }
        const id = ctx.pats.items.len;
        ctx.pats.append(ctx.a, pattern) catch unreachable;
        const fn_name = std2.fmt.allocPrint(ctx.a, "__koru_pt_{s}_{d}", .{ ctx.sfx, id }) catch unreachable;
        const src = regex.compilePrefixToZig(ctx.a, pattern, fn_name) catch |err| {
            setFail(ctx, std2.fmt.allocPrint(ctx.a, "std/parser: cannot compile terminal `{s}`: {s}", .{ zigEscape(ctx.a, pattern), @errorName(err) }) catch unreachable);
            return id;
        };
        ctx.matchers.appendSlice(ctx.a, src) catch unreachable;
        ctx.matchers.appendSlice(ctx.a, "\n") catch unreachable;
        return id;
    }

    /// The alternatives of a rule arm: its nested continuations (they hang
    /// off the arm whose node is the explicit match invocation).
    fn altsOf(rule: *const ast2.Continuation) []const ast2.Continuation {
        return rule.continuations;
    }

    /// Validate the rule's picker is the static shape this codegen
    /// partially evaluates: `std/parser:match(<cursor>)`. Any other body
    /// is legal protocol but not yet compiled — a loud wall.
    fn checkStaticPicker(ctx: *const Ctx, rule: *const ast2.Continuation) void {
        const n = rule.node orelse {
            setFail(ctx, std2.fmt.allocPrint(ctx.a, "std/parser: rule `{s}` has no picker — the static form is `! {s} <cursor> |> std/parser:match(<cursor>)`", .{ rule.branch, rule.branch }) catch unreachable);
            return;
        };
        if (n != .invocation or !isVerb(&n.invocation, "match")) {
            setFail(ctx, std2.fmt.allocPrint(ctx.a, "std/parser: rule `{s}`'s picker is not the static `std/parser:match(<cursor>)` shape — arbitrary pickers are the protocol, but only the static shape compiles today (loud wall, not a misparse)", .{rule.branch}) catch unreachable);
        }
    }

    /// Leftmost-cycle check: can a rule reach itself before consuming
    /// input? Walks the HEAD element of every alternative.
    fn leftRecurses(rules: []const ast2.Continuation, cont: *const ast2.Continuation, target: []const u8, visited: *std2.ArrayList([]const u8), a: std2.mem.Allocator) bool {
        for (altsOf(cont)) |*alt| {
            if (findRule(rules, alt.branch)) |sub_rule| {
                if (std2.mem.eql(u8, sub_rule.branch, target)) return true;
                var seen = false;
                for (visited.items) |v| {
                    if (std2.mem.eql(u8, v, sub_rule.branch)) seen = true;
                }
                if (!seen) {
                    visited.append(a, sub_rule.branch) catch unreachable;
                    if (leftRecurses(rules, sub_rule, target, visited, a)) return true;
                }
            }
        }
        return false;
    }

    /// Extract the produce expression from a chain-terminal node, if any.
    /// `-> expr` parses as an is_bare_return branch constructor (chain
    /// position) or a plain expression node (direct arm position).
    fn produceOf(node: *const ast2.Node) ?[]const u8 {
        switch (node.*) {
            .expression => |e| return e,
            .branch_constructor => |bc| {
                if (bc.is_bare_return) return bc.plain_value;
                return null;
            },
            else => return null,
        }
    }

    /// Emit one alternative's TAIL: bind the (already-parsed) head value,
    /// walk the chain steps, end in a produce-return (or the default
    /// consumed-span return). Falling out of the labeled block = this
    /// tail failed; the caller tries the next tail of the group.
    fn genTail(ctx: *const Ctx, out: *std2.ArrayList(u8), alt: *const ast2.Continuation, tail_label: usize, head_val: []const u8, head_end: []const u8) void {
        // Body goes to a scratch buffer first: a tail whose chain has no
        // failable step never breaks to its label, and Zig rejects unused
        // block labels — so the label is emitted only when targeted.
        var body = std2.ArrayList(u8){};
        const buf = &body;
        const open = std2.fmt.allocPrint(ctx.a, "__p = {s};\n", .{head_end}) catch unreachable;
        buf.appendSlice(ctx.a, open) catch unreachable;
        bindName(ctx, buf, alt.binding, head_val);

        // --- CHAIN: walk the alternative's body — sub / lit steps, then produce ---
        var produced = false;
        var node_opt: ?*const ast2.Node = if (alt.node) |*n| n else null;
        var cont_list: []const ast2.Continuation = alt.continuations;
        while (node_opt) |n| {
            if (produceOf(n)) |e| {
                const ret = std2.fmt.allocPrint(ctx.a, "return .{{ .end = __p, .val = ({s}) }};\n", .{e}) catch unreachable;
                buf.appendSlice(ctx.a, ret) catch unreachable;
                produced = true;
                break;
            }
            if (n.* != .invocation) {
                setFail(ctx, std2.fmt.allocPrint(ctx.a, "std/parser: an alternative's chain admits sub(<rule>), lit(\"...\"), and a trailing `-> expr` (cut 1)", .{}) catch unreachable);
                return;
            }
            const inv = &n.invocation;
            const sk = ctx.label_n.*;
            ctx.label_n.* += 1;
            if (isVerb(inv, "sub")) {
                if (inv.args.len == 0) {
                    setFail(ctx, std2.fmt.allocPrint(ctx.a, "std/parser: sub needs a rule: sub(<rule-name>)", .{}) catch unreachable);
                    return;
                }
                const rname = std2.mem.trim(u8, inv.args[0].value, " \t");
                if (findRule(ctx.rules, rname) == null) {
                    setFail(ctx, std2.fmt.allocPrint(ctx.a, "std/parser: sub({s}) names no rule of this grammar", .{rname}) catch unreachable);
                    return;
                }
                const rn = sanitize(ctx.a, rname);
                const step = std2.fmt.allocPrint(ctx.a, "const __s{d} = __koru_pr_{s}_{s}(input, __p, __err) orelse {{ if (__err.expected.len == 0 or __p > __err.pos) {{ __err.pos = __p; __err.expected = \"{s}\"; }} break :t{d}; }};\n", .{ sk, ctx.sfx, rn, zigEscape(ctx.a, rname), tail_label }) catch unreachable;
                buf.appendSlice(ctx.a, step) catch unreachable;
                bindName(ctx, buf, inv.return_binding, std2.fmt.allocPrint(ctx.a, "__s{d}.val", .{sk}) catch unreachable);
                const adv = std2.fmt.allocPrint(ctx.a, "__p = __s{d}.end;\n", .{sk}) catch unreachable;
                buf.appendSlice(ctx.a, adv) catch unreachable;
            } else if (isVerb(inv, "lit")) {
                if (inv.args.len == 0) {
                    setFail(ctx, std2.fmt.allocPrint(ctx.a, "std/parser: lit needs its text: lit(\"...\")", .{}) catch unreachable);
                    return;
                }
                const text = stripQuotes(inv.args[0].value);
                const esc = zigEscape(ctx.a, text);
                const step = std2.fmt.allocPrint(ctx.a, "if (!(__p + {d} <= input.len and __koru_lit_eq_{s}(input[__p .. __p + {d}], \"{s}\"))) {{ if (__err.expected.len == 0 or __p > __err.pos) {{ __err.pos = __p; __err.expected = \"{s}\"; }} break :t{d}; }}\n__p += {d};\n", .{ text.len, ctx.sfx, text.len, esc, esc, tail_label, text.len }) catch unreachable;
                buf.appendSlice(ctx.a, step) catch unreachable;
            } else {
                setFail(ctx, std2.fmt.allocPrint(ctx.a, "std/parser: `{s}` is not grammar vocabulary — an alternative's chain admits sub(<rule>) and lit(\"...\") (cut 1)", .{inv.path.segments[inv.path.segments.len - 1]}) catch unreachable);
                return;
            }
            // Follow the chain: the next step is the single empty-branch child.
            node_opt = null;
            if (cont_list.len == 1 and cont_list[0].branch.len == 0) {
                node_opt = if (cont_list[0].node) |*nn| nn else null;
                cont_list = cont_list[0].continuations;
            } else if (cont_list.len > 0) {
                setFail(ctx, std2.fmt.allocPrint(ctx.a, "std/parser: an alternative's chain is linear — nested branching inside an alternative is cut 2", .{}) catch unreachable);
                return;
            }
        }
        if (!produced) {
            // No `->`: the alternative's value defaults to its consumed span.
            buf.appendSlice(ctx.a, "return .{ .end = __p, .val = input[__start..__p] };\n") catch unreachable;
        }
        const needle = std2.fmt.allocPrint(ctx.a, "break :t{d};", .{tail_label}) catch unreachable;
        const labeled = std2.mem.indexOf(u8, body.items, needle) != null;
        const wrap = if (labeled)
            std2.fmt.allocPrint(ctx.a, "t{d}: {{\n", .{tail_label}) catch unreachable
        else
            std2.fmt.allocPrint(ctx.a, "{{\n", .{}) catch unreachable;
        out.appendSlice(ctx.a, wrap) catch unreachable;
        out.appendSlice(ctx.a, body.items) catch unreachable;
        out.appendSlice(ctx.a, "}\n") catch unreachable;
    }

    /// Emit one GROUP: consecutive alternatives sharing the same head
    /// element. The head parses ONCE; each alternative's tail then tries
    /// in order against the saved head result. Sound because cut-1 rule
    /// functions are deterministic (same position in, same result out) —
    /// PEG's backtracking reparse of a shared head is guaranteed to
    /// reproduce the first parse, so skipping it is unobservable. This
    /// converts the `item sep rest | item` last-element reparse from
    /// exponential (right-nested input) to linear.
    fn genGroup(ctx: *const Ctx, buf: *std2.ArrayList(u8), alts: []const ast2.Continuation, cp_label: usize) void {
        for (alts) |*alt| {
            if (alt.kind != .terminal) {
                setFail(ctx, std2.fmt.allocPrint(ctx.a, "std/parser: alternatives are `|` patterned branches of match (`!` has no meaning here)", .{}) catch unreachable);
                return;
            }
            if (alt.destructure.len > 0) {
                setFail(ctx, std2.fmt.allocPrint(ctx.a, "std/parser: destructure in an alternative waits on typed captures (cut 2) — bind the span", .{}) catch unreachable);
                return;
            }
        }
        const g = ctx.label_n.*;
        ctx.label_n.* += 1;

        const open = std2.fmt.allocPrint(ctx.a, "__p = __cp{d};\ng{d}: {{\n", .{ cp_label, g }) catch unreachable;
        buf.appendSlice(ctx.a, open) catch unreachable;

        // --- HEAD (identical across the group): rule reference or pattern terminal, parsed once ---
        const head_name = alts[0].branch;

        // --- FIRST-BYTE GATE (rung 1): only enter the group when the byte at
        // the cursor can begin the head. A gated-out group is exactly one
        // whose head-match would fail on byte 1 — same PEG order, the reject
        // just happens without the matcher call.
        //
        // PATTERN heads only. A pattern head's admissible first bytes come
        // straight from its prefix DFA, and the head text IS the diagnostic —
        // so the miss path (cold: errors aren't hot) records the very same
        // furthest-failure `(pos, expected-terminal)` the matcher `orelse`
        // would, and the message is byte-for-byte the ungated one. RULE heads
        // are deliberately NOT gated: skipping a rule's descent would rob the
        // deepest terminal of its chance to record, coarsening `expected
        // <terminal>` into `expected <rule>`. Keeping the specific wall beats
        // the marginal saving of gating an already-internally-gated sub-call.
        if (findRule(ctx.rules, head_name) == null) {
            const fb = regex.prefixFirstBytes(ctx.a, head_name) catch [_]bool{true} ** 256;
            var gate_all = true;
            for (fb) |x| {
                if (!x) {
                    gate_all = false;
                    break;
                }
            }
            if (!gate_all) {
                var arr = std2.ArrayList(u8){};
                arr.appendSlice(ctx.a, std2.fmt.allocPrint(ctx.a, "const __fb{d} = [_]bool{{", .{g}) catch unreachable) catch unreachable;
                for (fb, 0..) |x, bi| {
                    const cell = if (bi == 0) (if (x) "true" else "false") else (if (x) ",true" else ",false");
                    arr.appendSlice(ctx.a, cell) catch unreachable;
                }
                arr.appendSlice(ctx.a, "};\n") catch unreachable;
                buf.appendSlice(ctx.a, arr.items) catch unreachable;
                const gate = std2.fmt.allocPrint(ctx.a, "if (__cp{d} >= input.len or !__fb{d}[input[__cp{d}]]) {{ if (__err.expected.len == 0 or __cp{d} > __err.pos) {{ __err.pos = __cp{d}; __err.expected = \"{s}\"; }} break :g{d}; }}\n", .{ cp_label, g, cp_label, cp_label, cp_label, zigEscape(ctx.a, head_name), g }) catch unreachable;
                buf.appendSlice(ctx.a, gate) catch unreachable;
            }
        }
        var head_val: []const u8 = undefined;
        var head_end: []const u8 = undefined;
        if (findRule(ctx.rules, head_name)) |_| {
            const rn = sanitize(ctx.a, head_name);
            const head = std2.fmt.allocPrint(ctx.a, "const __gh{d} = __koru_pr_{s}_{s}(input, __p, __err) orelse {{ if (__err.expected.len == 0 or __p > __err.pos) {{ __err.pos = __p; __err.expected = \"{s}\"; }} break :g{d}; }};\n", .{ g, ctx.sfx, rn, zigEscape(ctx.a, head_name), g }) catch unreachable;
            buf.appendSlice(ctx.a, head) catch unreachable;
            head_val = std2.fmt.allocPrint(ctx.a, "__gh{d}.val", .{g}) catch unreachable;
            head_end = std2.fmt.allocPrint(ctx.a, "__gh{d}.end", .{g}) catch unreachable;
        } else {
            const id = matcherFor(ctx, head_name);
            const head = std2.fmt.allocPrint(ctx.a, "const __ge{d} = __koru_pt_{s}_{d}(input, __p) orelse {{ if (__err.expected.len == 0 or __p > __err.pos) {{ __err.pos = __p; __err.expected = \"{s}\"; }} break :g{d}; }};\n", .{ g, ctx.sfx, id, zigEscape(ctx.a, head_name), g }) catch unreachable;
            buf.appendSlice(ctx.a, head) catch unreachable;
            head_val = std2.fmt.allocPrint(ctx.a, "input[__cp{d}..__ge{d}]", .{ cp_label, g }) catch unreachable;
            head_end = std2.fmt.allocPrint(ctx.a, "__ge{d}", .{g}) catch unreachable;
        }

        // --- TAILS: in declaration order; falling out of the group = all failed ---
        for (alts) |*alt| {
            const t = ctx.label_n.*;
            ctx.label_n.* += 1;
            genTail(ctx, buf, alt, t, head_val, head_end);
        }
        buf.appendSlice(ctx.a, "}\n") catch unreachable;
    }

    fn bindName(ctx: *const Ctx, buf: *std2.ArrayList(u8), name_opt: ?[]const u8, val_expr: []const u8) void {
        const name = name_opt orelse return;
        if (std2.mem.eql(u8, name, "_")) return;
        const bind = std2.fmt.allocPrint(ctx.a, "const {s} = {s}; _ = &{s};\n", .{ name, val_expr, name }) catch unreachable;
        buf.appendSlice(ctx.a, bind) catch unreachable;
    }

    fn genRuleFn(ctx: *const Ctx, rule: *const ast2.Continuation) void {
        const rn = sanitize(ctx.a, rule.branch);
        var buf = std2.ArrayList(u8){};
        const head = std2.fmt.allocPrint(ctx.a, "fn __koru_pr_{s}_{s}(input: []const u8, pos: usize, __err: *__koru_perr_{s}) ?__koru_pres_{s} {{\nconst __start = pos; _ = &__start;\nvar __p: usize = pos;\n", .{ ctx.sfx, rn, ctx.sfx, ctx.sfx }) catch unreachable;
        buf.appendSlice(ctx.a, head) catch unreachable;
        const cp = ctx.label_n.*;
        ctx.label_n.* += 1;
        const cpl = std2.fmt.allocPrint(ctx.a, "const __cp{d} = pos;\n", .{cp}) catch unreachable;
        buf.appendSlice(ctx.a, cpl) catch unreachable;
        // Group CONSECUTIVE same-head alternatives so the shared head
        // parses once (genGroup). Non-adjacent same-heads keep strict
        // declaration order — only adjacency factors.
        const alts = altsOf(rule);
        var i: usize = 0;
        while (i < alts.len) {
            var j = i + 1;
            while (j < alts.len and std2.mem.eql(u8, alts[j].branch, alts[i].branch)) j += 1;
            genGroup(ctx, &buf, alts[i..j], cp);
            i = j;
        }
        buf.appendSlice(ctx.a, "return null;\n}\n") catch unreachable;
        ctx.matchers.appendSlice(ctx.a, buf.items) catch unreachable;
    }
};

if (item.* != .flow) @panic("std/parser parse transform: containing item is not a flow - walker dispatch contract broken");
const flow = &item.flow;
const conts = flow.body.continuations;

// --- Arguments: parse(<input expr>, grammar: <name>) ---
if (invocation.args.len == 0) {
    const msg = std.fmt.allocPrint(allocator, "comptime {{ @compileError(\"std/parser:parse requires an input: parse(<expression>, grammar: <name>)\"); }}", .{}) catch unreachable;
    return .{ .transformed = .{ .replacement = ast.Item{ .inline_code = ast.InlineCode{ .code = msg, .location = flow.location, .module = flow.module } } } };
}
const input_expr: []const u8 = invocation.args[0].value;
var grammar_name: ?[]const u8 = null;
for (invocation.args) |arg| {
    if (std.mem.eql(u8, arg.name, "grammar")) grammar_name = std.mem.trim(u8, arg.value, " \t");
}
if (grammar_name == null) {
    const msg = std.fmt.allocPrint(allocator, "comptime {{ @compileError(\"std/parser:parse needs its grammar named: parse(<input>, grammar: <name>)\"); }}", .{}) catch unreachable;
    return .{ .transformed = .{ .replacement = ast.Item{ .inline_code = ast.InlineCode{ .code = msg, .location = flow.location, .module = flow.module } } } };
}

// --- Locate the grammar region in the program ---
var rules: ?[]const ast.Continuation = null;
for (program.items) |*it| {
    if (it.* != .flow) continue;
    const g = &it.flow;
    const p = g.inv().path;
    if (p.segments.len != 1 or !std.mem.eql(u8, p.segments[0], "grammar")) continue;
    const q = p.module_qualifier orelse continue;
    if (!std.mem.endsWith(u8, q, "parser")) continue;
    if (g.inv().args.len == 0) continue;
    if (!std.mem.eql(u8, std.mem.trim(u8, g.inv().args[0].value, " \t"), grammar_name.?)) continue;
    rules = g.body.continuations;
    break;
}
if (rules == null) {
    const msg = std.fmt.allocPrint(allocator, "comptime {{ @compileError(\"std/parser:parse: no grammar named `{s}` in this program — declare it: std/parser:grammar({s}) with `! <rule> <cursor>` arms\"); }}", .{ grammar_name.?, grammar_name.? }) catch unreachable;
    return .{ .transformed = .{ .replacement = ast.Item{ .inline_code = ast.InlineCode{ .code = msg, .location = flow.location, .module = flow.module } } } };
}

// --- Parse-site branches: exactly one top rule + optional parse-error ---
var top_idx: ?usize = null;
var err_idx: ?usize = null;
for (conts, 0..) |c, i| {
    if (std.mem.eql(u8, c.branch, "parse-error")) {
        err_idx = i;
        continue;
    }
    if (top_idx != null) {
        const msg = std.fmt.allocPrint(allocator, "comptime {{ @compileError(\"std/parser:parse dispatches ONE top rule (plus optional parse-error); found a second branch `{s}`\"); }}", .{c.branch}) catch unreachable;
        return .{ .transformed = .{ .replacement = ast.Item{ .inline_code = ast.InlineCode{ .code = msg, .location = flow.location, .module = flow.module } } } };
    }
    top_idx = i;
}
if (top_idx == null) {
    const msg = std.fmt.allocPrint(allocator, "comptime {{ @compileError(\"std/parser:parse needs a top-rule branch: `| <rule> <binding> |> ...`\"); }}", .{}) catch unreachable;
    return .{ .transformed = .{ .replacement = ast.Item{ .inline_code = ast.InlineCode{ .code = msg, .location = flow.location, .module = flow.module } } } };
}
const top = conts[top_idx.?];
if (H.findRule(rules.?, top.branch) == null) {
    const msg = std.fmt.allocPrint(allocator, "comptime {{ @compileError(\"std/parser:parse: `{s}` is not a rule of grammar `{s}`\"); }}", .{ top.branch, grammar_name.? }) catch unreachable;
    return .{ .transformed = .{ .replacement = ast.Item{ .inline_code = ast.InlineCode{ .code = msg, .location = flow.location, .module = flow.module } } } };
}

// --- Left recursion: reject loudly, name the fix ---
for (rules.?) |*r| {
    var visited = std.ArrayList([]const u8){};
    if (H.leftRecurses(rules.?, r, r.branch, &visited, allocator)) {
        const msg = std.fmt.allocPrint(allocator, "comptime {{ @compileError(\"std/parser: rule `{s}` is left-recursive (it can call itself before consuming input) — rewrite right-recursively: put a consuming element (a terminal) first\"); }}", .{r.branch}) catch unreachable;
        return .{ .transformed = .{ .replacement = ast.Item{ .inline_code = ast.InlineCode{ .code = msg, .location = flow.location, .module = flow.module } } } };
    }
}

// --- Generate: error/result structs, lit helper, terminal matchers, rule fns ---
const sfx = std.fmt.allocPrint(allocator, "{d}_{d}", .{ flow.location.line, flow.location.column }) catch unreachable;
var matchers = std.ArrayList(u8){};
var pats = std.ArrayList([]const u8){};
var label_n: usize = 0;
var fail: ?[]const u8 = null;
const ctx = H.Ctx{ .a = allocator, .sfx = sfx, .rules = rules.?, .matchers = &matchers, .pats = &pats, .label_n = &label_n, .fail = &fail };

const structs = std.fmt.allocPrint(allocator, "const __koru_perr_{s} = struct {{ pos: usize = 0, expected: []const u8 = \"\" }};\nconst __koru_pres_{s} = struct {{ end: usize, val: []const u8 }};\nfn __koru_lit_eq_{s}(a: []const u8, b: []const u8) bool {{ if (a.len != b.len) return false; for (a, b) |x, y| {{ if (x != y) return false; }} return true; }}\n", .{ sfx, sfx, sfx }) catch unreachable;
matchers.appendSlice(allocator, structs) catch unreachable;

for (rules.?) |*r| H.checkStaticPicker(&ctx, r);
for (rules.?) |*r| H.genRuleFn(&ctx, r);

if (fail) |f| {
    const msg = std.fmt.allocPrint(allocator, "comptime {{ @compileError(\"{s}\"); }}", .{f}) catch unreachable;
    return .{ .transformed = .{ .replacement = ast.Item{ .inline_code = ast.InlineCode{ .code = msg, .location = flow.location, .module = flow.module } } } };
}

// --- Dispatch splice ---
var dispatch = std.ArrayList(u8){};
const head = std.fmt.allocPrint(allocator, "//@koru:inline_stmt\n{{ const __koru_pin: []const u8 = {s};\nvar __koru_pe: __koru_perr_{s} = .{{}};\n", .{ input_expr, sfx }) catch unreachable;
dispatch.appendSlice(allocator, head) catch unreachable;

// parse-error splice: line/col by newline count at the furthest failure.
var errsplice: []const u8 = "@panic(\"std/parser: parse error (no parse-error branch to deliver it)\");";
if (err_idx) |ei| {
    errsplice = std.fmt.allocPrint(allocator,
        \\{{ var __l: usize = 1; var __c: usize = 1;
        \\const __ep = @min(__koru_pe.pos, __koru_pin.len);
        \\for (__koru_pin[0..__ep]) |__ch| {{ if (__ch == '\n') {{ __l += 1; __c = 1; }} else {{ __c += 1; }} }}
        \\const __found: []const u8 = if (__koru_pe.pos < __koru_pin.len) __koru_pin[__koru_pe.pos .. __koru_pe.pos + 1] else "end of input";
        \\_ = &__found; __koru_inline_{d}(.{{ .line = __l, .col = __c, .expected = __koru_pe.expected, .found = __found }}); }}
    , .{ei}) catch unreachable;
}

const rn = H.sanitize(allocator, top.branch);
const body = std.fmt.allocPrint(allocator, "if (__koru_pr_{s}_{s}(__koru_pin, 0, &__koru_pe)) |__koru_pres| {{\nif (__koru_pres.end == __koru_pin.len) {{ __koru_inline_{d}(__koru_pres.val); }}\nelse {{ if (__koru_pe.expected.len == 0 or __koru_pres.end > __koru_pe.pos) {{ __koru_pe.pos = __koru_pres.end; __koru_pe.expected = \"end of input\"; }}\n{s} }}\n}} else {{\n{s} }}\n}}", .{ sfx, rn, top_idx.?, errsplice, errsplice }) catch unreachable;
dispatch.appendSlice(allocator, body) catch unreachable;

// --- Rebuild the flow: @pass_ran, dispatch inline_body, continuations kept ---
const new_anns = allocator.alloc([]const u8, flow.inv().annotations.len + 1) catch unreachable;
for (flow.inv().annotations, 0..) |an, k| new_anns[k] = an;
new_anns[flow.inv().annotations.len] = allocator.dupe(u8, "@pass_ran(\"transform\")") catch unreachable;

const new_inv = ast.Invocation{
    .path = flow.inv().path,
    .args = flow.inv().args,
    .annotations = new_anns,
    .inserted_by_tap = flow.inv().inserted_by_tap,
    .from_opaque_tap = flow.inv().from_opaque_tap,
};

var new_flow = flow.*;
new_flow.body = ast.rootSite(new_inv, flow.body.continuations, flow.location);
new_flow.inline_body = dispatch.toOwnedSlice(allocator) catch unreachable;

const appended = allocator.alloc(ast.Item, 1) catch unreachable;
appended[0] = ast.Item{ .inline_code = ast.InlineCode{
    .code = matchers.toOwnedSlice(allocator) catch unreachable,
    .location = flow.location,
    .module = flow.module,
} };

return .{ .transformed = .{ .replacement = ast.Item{ .flow = new_flow }, .appended = appended } };

const ast = @import("ast");

// --- Target: bare positional (`generate c`) or `--lang=<x>`; default c ---
var target: []const u8 = "c";
for (argv) |a| {
    if (std.mem.startsWith(u8, a, "--lang=")) {
        target = a["--lang=".len..];
    } else if (a.len > 0 and a[0] != '-') {
        target = a;
    }
}

// --- Find the first grammar region in the program (mirror parse's walk) ---
var found_rules: ?[]const ast.Continuation = null;
var gname: []const u8 = "";
for (program.items) |*it| {
    if (it.* != .flow) continue;
    const g = &it.flow;
    const p = g.inv().path;
    if (p.segments.len != 1 or !std.mem.eql(u8, p.segments[0], "grammar")) continue;
    const q = p.module_qualifier orelse continue;
    if (!std.mem.endsWith(u8, q, "parser")) continue;
    if (g.inv().args.len == 0) continue;
    gname = std.mem.trim(u8, g.inv().args[0].value, " \t");
    found_rules = g.body.continuations;
    break;
}

if (found_rules == null) {
    std.debug.print("std/parser generate: no grammar region found in this program\n", .{});
    std.process.exit(1);
}

if (!std.mem.eql(u8, target, "c")) {
    std.debug.print("std/parser generate: target '{s}' is not implemented — only 'c' today (loud wall, not a silent fallback)\n", .{target});
    std.process.exit(1);
}

// ================= C EMITTER =================
// Mirrors the parse|zig helper container. Re-imports what it needs; fn-scope
// containers cannot reach fn-scope consts, so it uses std2/ast2/regex.
const C = struct {
    const std2 = @import("std");
    const ast2 = @import("ast");
    const regex = @import("regex_engine");

    const Ctx = struct {
        a: std2.mem.Allocator,
        rules: []const ast2.Continuation,
        out: *std2.ArrayList(u8), // rule fn definitions
        matchers: *std2.ArrayList(u8), // terminal DFA matcher fns
        pats: *std2.ArrayList([]const u8), // distinct patterns (index = matcher id)
        label_n: *usize,
        fail: *?[]const u8,
    };

    // C string-literal escaping — same admissible set as the Zig emitter.
    fn cEscape(a: std2.mem.Allocator, s: []const u8) []const u8 {
        var buf = std2.ArrayList(u8){};
        for (s) |ch| {
            switch (ch) {
                '"' => buf.appendSlice(a, "\\\"") catch unreachable,
                '\\' => buf.appendSlice(a, "\\\\") catch unreachable,
                '\n' => buf.appendSlice(a, "\\n") catch unreachable,
                '\r' => buf.appendSlice(a, "\\r") catch unreachable,
                '\t' => buf.appendSlice(a, "\\t") catch unreachable,
                else => buf.append(a, ch) catch unreachable,
            }
        }
        return buf.toOwnedSlice(a) catch unreachable;
    }

    fn sanitize(a: std2.mem.Allocator, s: []const u8) []const u8 {
        const out = a.dupe(u8, s) catch unreachable;
        for (out) |*ch| {
            if (!((ch.* >= 'a' and ch.* <= 'z') or (ch.* >= 'A' and ch.* <= 'Z') or (ch.* >= '0' and ch.* <= '9'))) ch.* = '_';
        }
        return out;
    }

    fn findRule(rules: []const ast2.Continuation, name: []const u8) ?*const ast2.Continuation {
        for (rules) |*r| {
            if (std2.mem.eql(u8, r.branch, name)) return r;
        }
        return null;
    }

    fn setFail(ctx: *const Ctx, msg: []const u8) void {
        if (ctx.fail.* == null) ctx.fail.* = msg;
    }

    // NOTE: unlike parse|zig's isVerb, this does NOT require the module
    // qualifier to end in "parser". The `generate` command runs on the RAW
    // seed AST — resolve-with-scopes (which stamps `std/parser` onto the
    // [with]-opened `sub`/`lit`/`match` names) lives in coordinate, which the
    // command bypasses. So the verbs arrive main-module-stamped; inside a
    // validated grammar region the single-segment name is unambiguous.
    fn isVerb(inv: *const ast2.Invocation, verb: []const u8) bool {
        return inv.path.segments.len == 1 and std2.mem.eql(u8, inv.path.segments[0], verb);
    }

    fn stripQuotes(s: []const u8) []const u8 {
        const t = std2.mem.trim(u8, s, " \t");
        if (t.len >= 2 and t[0] == '"' and t[t.len - 1] == '"') return t[1 .. t.len - 1];
        return t;
    }

    // Matcher id for a terminal pattern, compiling it to C on first sight.
    fn matcherFor(ctx: *const Ctx, pattern: []const u8) usize {
        for (ctx.pats.items, 0..) |p, i| {
            if (std2.mem.eql(u8, p, pattern)) return i;
        }
        const id = ctx.pats.items.len;
        ctx.pats.append(ctx.a, pattern) catch unreachable;
        const fn_name = std2.fmt.allocPrint(ctx.a, "__koru_pt_{d}", .{id}) catch unreachable;
        const src = regex.compilePrefixToC(ctx.a, pattern, fn_name) catch |err| {
            setFail(ctx, std2.fmt.allocPrint(ctx.a, "std/parser generate: cannot compile terminal `{s}`: {s}", .{ cEscape(ctx.a, pattern), @errorName(err) }) catch unreachable);
            return id;
        };
        ctx.matchers.appendSlice(ctx.a, src) catch unreachable;
        ctx.matchers.appendSlice(ctx.a, "\n") catch unreachable;
        return id;
    }

    fn altsOf(rule: *const ast2.Continuation) []const ast2.Continuation {
        return rule.continuations;
    }

    fn produceOf(node: *const ast2.Node) ?[]const u8 {
        switch (node.*) {
            .expression => |e| return e,
            .branch_constructor => |bc| {
                if (bc.is_bare_return) return bc.plain_value;
                return null;
            },
            else => return null,
        }
    }

    // `const koru_slice NAME = EXPR; (void)NAME;` — skip `_` / unbound.
    fn bindName(ctx: *const Ctx, buf: *std2.ArrayList(u8), name_opt: ?[]const u8, val_expr: []const u8) void {
        const name = name_opt orelse return;
        if (std2.mem.eql(u8, name, "_")) return;
        const bind = std2.fmt.allocPrint(ctx.a, "const koru_slice {s} = {s}; (void){s};\n", .{ name, val_expr, name }) catch unreachable;
        buf.appendSlice(ctx.a, bind) catch unreachable;
    }

    // One alternative's TAIL: bind the head value, walk the chain, end in a
    // produce (or default consumed-span). Falling to the tail's goto label =
    // this tail failed; control drops to the next tail of the group.
    fn genTail(ctx: *const Ctx, out: *std2.ArrayList(u8), alt: *const ast2.Continuation, tail_label: usize, head_val: []const u8, head_end: []const u8) void {
        var body = std2.ArrayList(u8){};
        const buf = &body;
        buf.appendSlice(ctx.a, std2.fmt.allocPrint(ctx.a, "__p = {s};\n", .{head_end}) catch unreachable) catch unreachable;
        bindName(ctx, buf, alt.binding, head_val);

        var produced = false;
        var node_opt: ?*const ast2.Node = if (alt.node) |*n| n else null;
        var cont_list: []const ast2.Continuation = alt.continuations;
        while (node_opt) |n| {
            if (produceOf(n)) |e| {
                buf.appendSlice(ctx.a, std2.fmt.allocPrint(ctx.a, "*out = (koru_pres){{ __p, ({s}) }}; return true;\n", .{e}) catch unreachable) catch unreachable;
                produced = true;
                break;
            }
            if (n.* != .invocation) {
                setFail(ctx, "std/parser generate: an alternative's chain admits sub(<rule>), lit(\"...\"), and a trailing `-> expr` (cut 1)");
                return;
            }
            const inv = &n.invocation;
            const sk = ctx.label_n.*;
            ctx.label_n.* += 1;
            if (isVerb(inv, "sub")) {
                if (inv.args.len == 0) {
                    setFail(ctx, "std/parser generate: sub needs a rule: sub(<rule-name>)");
                    return;
                }
                const rname = std2.mem.trim(u8, inv.args[0].value, " \t");
                if (findRule(ctx.rules, rname) == null) {
                    setFail(ctx, std2.fmt.allocPrint(ctx.a, "std/parser generate: sub({s}) names no rule of this grammar", .{rname}) catch unreachable);
                    return;
                }
                const rn = sanitize(ctx.a, rname);
                buf.appendSlice(ctx.a, std2.fmt.allocPrint(ctx.a, "koru_pres __s{d};\n", .{sk}) catch unreachable) catch unreachable;
                buf.appendSlice(ctx.a, std2.fmt.allocPrint(ctx.a, "if (!__koru_pr_{s}(input, len, __p, err, &__s{d})) {{ if (err->expected == 0 || __p > err->pos) {{ err->pos = __p; err->expected = \"{s}\"; }} goto Lt{d}_end; }}\n", .{ rn, sk, cEscape(ctx.a, rname), tail_label }) catch unreachable) catch unreachable;
                bindName(ctx, buf, inv.return_binding, std2.fmt.allocPrint(ctx.a, "__s{d}.val", .{sk}) catch unreachable);
                buf.appendSlice(ctx.a, std2.fmt.allocPrint(ctx.a, "__p = __s{d}.end;\n", .{sk}) catch unreachable) catch unreachable;
            } else if (isVerb(inv, "lit")) {
                if (inv.args.len == 0) {
                    setFail(ctx, "std/parser generate: lit needs its text: lit(\"...\")");
                    return;
                }
                const text = stripQuotes(inv.args[0].value);
                const esc = cEscape(ctx.a, text);
                buf.appendSlice(ctx.a, std2.fmt.allocPrint(ctx.a, "if (!(__p + {d} <= len && __koru_lit_eq(input + __p, {d}, \"{s}\", {d}))) {{ if (err->expected == 0 || __p > err->pos) {{ err->pos = __p; err->expected = \"{s}\"; }} goto Lt{d}_end; }}\n__p += {d};\n", .{ text.len, text.len, esc, text.len, esc, tail_label, text.len }) catch unreachable) catch unreachable;
            } else {
                setFail(ctx, std2.fmt.allocPrint(ctx.a, "std/parser generate: `{s}` is not grammar vocabulary — a chain admits sub(<rule>) and lit(\"...\") (cut 1)", .{inv.path.segments[inv.path.segments.len - 1]}) catch unreachable);
                return;
            }
            node_opt = null;
            if (cont_list.len == 1 and cont_list[0].branch.len == 0) {
                node_opt = if (cont_list[0].node) |*nn| nn else null;
                cont_list = cont_list[0].continuations;
            } else if (cont_list.len > 0) {
                setFail(ctx, "std/parser generate: an alternative's chain is linear — nested branching inside an alternative is cut 2");
                return;
            }
        }
        if (!produced) {
            buf.appendSlice(ctx.a, "*out = (koru_pres){ __p, (koru_slice){ input + __start, __p - __start } }; return true;\n") catch unreachable;
        }
        const needle = std2.fmt.allocPrint(ctx.a, "goto Lt{d}_end;", .{tail_label}) catch unreachable;
        const labeled = std2.mem.indexOf(u8, body.items, needle) != null;
        out.appendSlice(ctx.a, "{\n") catch unreachable;
        out.appendSlice(ctx.a, body.items) catch unreachable;
        out.appendSlice(ctx.a, "}\n") catch unreachable;
        if (labeled) {
            out.appendSlice(ctx.a, std2.fmt.allocPrint(ctx.a, "Lt{d}_end: ;\n", .{tail_label}) catch unreachable) catch unreachable;
        }
    }

    // One GROUP: consecutive alternatives sharing the same head element. The
    // head parses ONCE (sound by cut-1 determinism); each tail then tries in
    // order. First-byte gate on pattern heads (rung 1).
    fn genGroup(ctx: *const Ctx, buf: *std2.ArrayList(u8), alts: []const ast2.Continuation, cp_label: usize) void {
        for (alts) |*alt| {
            if (alt.kind != .terminal) {
                setFail(ctx, "std/parser generate: alternatives are `|` patterned branches of match");
                return;
            }
            if (alt.destructure.len > 0) {
                setFail(ctx, "std/parser generate: destructure in an alternative waits on typed captures (cut 2) — bind the span");
                return;
            }
        }
        const g = ctx.label_n.*;
        ctx.label_n.* += 1;

        buf.appendSlice(ctx.a, std2.fmt.allocPrint(ctx.a, "__p = __cp{d};\n{{\n", .{cp_label}) catch unreachable) catch unreachable;

        const head_name = alts[0].branch;

        // First-byte gate — PATTERN heads only (rule heads must descend so the
        // deepest terminal records the furthest failure).
        if (findRule(ctx.rules, head_name) == null) {
            const fb = regex.prefixFirstBytes(ctx.a, head_name) catch [_]bool{true} ** 256;
            var gate_all = true;
            for (fb) |x| {
                if (!x) {
                    gate_all = false;
                    break;
                }
            }
            if (!gate_all) {
                var arr = std2.ArrayList(u8){};
                arr.appendSlice(ctx.a, std2.fmt.allocPrint(ctx.a, "static const bool __fb{d}[256] = {{", .{g}) catch unreachable) catch unreachable;
                for (fb, 0..) |x, bi| {
                    const cell = if (bi == 0) (if (x) "true" else "false") else (if (x) ",true" else ",false");
                    arr.appendSlice(ctx.a, cell) catch unreachable;
                }
                arr.appendSlice(ctx.a, "};\n") catch unreachable;
                buf.appendSlice(ctx.a, arr.items) catch unreachable;
                buf.appendSlice(ctx.a, std2.fmt.allocPrint(ctx.a, "if (__cp{d} >= len || !__fb{d}[input[__cp{d}]]) {{ if (err->expected == 0 || __cp{d} > err->pos) {{ err->pos = __cp{d}; err->expected = \"{s}\"; }} goto Lg{d}_end; }}\n", .{ cp_label, g, cp_label, cp_label, cp_label, cEscape(ctx.a, head_name), g }) catch unreachable) catch unreachable;
            }
        }

        // Head parse — rule reference or pattern terminal, once.
        if (findRule(ctx.rules, head_name)) |_| {
            const rn = sanitize(ctx.a, head_name);
            buf.appendSlice(ctx.a, std2.fmt.allocPrint(ctx.a, "koru_pres __gh{d};\n", .{g}) catch unreachable) catch unreachable;
            buf.appendSlice(ctx.a, std2.fmt.allocPrint(ctx.a, "if (!__koru_pr_{s}(input, len, __p, err, &__gh{d})) {{ if (err->expected == 0 || __p > err->pos) {{ err->pos = __p; err->expected = \"{s}\"; }} goto Lg{d}_end; }}\n", .{ rn, g, cEscape(ctx.a, head_name), g }) catch unreachable) catch unreachable;
            buf.appendSlice(ctx.a, std2.fmt.allocPrint(ctx.a, "koru_slice __hv{d} = __gh{d}.val; size_t __he{d} = __gh{d}.end; (void)__hv{d};\n", .{ g, g, g, g, g }) catch unreachable) catch unreachable;
        } else {
            const id = matcherFor(ctx, head_name);
            buf.appendSlice(ctx.a, std2.fmt.allocPrint(ctx.a, "size_t __ge{d} = __koru_pt_{d}(input, len, __p);\n", .{ g, id }) catch unreachable) catch unreachable;
            buf.appendSlice(ctx.a, std2.fmt.allocPrint(ctx.a, "if (__ge{d} == SIZE_MAX) {{ if (err->expected == 0 || __p > err->pos) {{ err->pos = __p; err->expected = \"{s}\"; }} goto Lg{d}_end; }}\n", .{ g, cEscape(ctx.a, head_name), g }) catch unreachable) catch unreachable;
            buf.appendSlice(ctx.a, std2.fmt.allocPrint(ctx.a, "koru_slice __hv{d} = (koru_slice){{ input + __cp{d}, __ge{d} - __cp{d} }}; size_t __he{d} = __ge{d}; (void)__hv{d};\n", .{ g, cp_label, g, cp_label, g, g, g }) catch unreachable) catch unreachable;
        }
        const head_val = std2.fmt.allocPrint(ctx.a, "__hv{d}", .{g}) catch unreachable;
        const head_end = std2.fmt.allocPrint(ctx.a, "__he{d}", .{g}) catch unreachable;

        for (alts) |*alt| {
            const t = ctx.label_n.*;
            ctx.label_n.* += 1;
            genTail(ctx, buf, alt, t, head_val, head_end);
        }
        buf.appendSlice(ctx.a, std2.fmt.allocPrint(ctx.a, "}}\nLg{d}_end: ;\n", .{g}) catch unreachable) catch unreachable;
    }

    fn genRuleFn(ctx: *const Ctx, rule: *const ast2.Continuation) void {
        const rn = sanitize(ctx.a, rule.branch);
        var buf = std2.ArrayList(u8){};
        buf.appendSlice(ctx.a, std2.fmt.allocPrint(ctx.a, "static bool __koru_pr_{s}(const uint8_t* input, size_t len, size_t pos, koru_perr* err, koru_pres* out) {{\nsize_t __start = pos; (void)__start;\nsize_t __p = pos;\n", .{rn}) catch unreachable) catch unreachable;
        const cp = ctx.label_n.*;
        ctx.label_n.* += 1;
        buf.appendSlice(ctx.a, std2.fmt.allocPrint(ctx.a, "size_t __cp{d} = pos; (void)__cp{d};\n", .{ cp, cp }) catch unreachable) catch unreachable;
        const alts = altsOf(rule);
        var i: usize = 0;
        while (i < alts.len) {
            var j = i + 1;
            while (j < alts.len and std2.mem.eql(u8, alts[j].branch, alts[i].branch)) j += 1;
            genGroup(ctx, &buf, alts[i..j], cp);
            i = j;
        }
        buf.appendSlice(ctx.a, "return false;\n}\n") catch unreachable;
        ctx.out.appendSlice(ctx.a, buf.items) catch unreachable;
    }
};

// --- Run the emitter ---
var out = std.ArrayList(u8){};
var matchers = std.ArrayList(u8){};
var pats = std.ArrayList([]const u8){};
var label_n: usize = 0;
var fail: ?[]const u8 = null;
const ctx = C.Ctx{ .a = allocator, .rules = found_rules.?, .out = &out, .matchers = &matchers, .pats = &pats, .label_n = &label_n, .fail = &fail };

for (found_rules.?) |*r| C.genRuleFn(&ctx, r);

if (fail) |f| {
    std.debug.print("{s}\n", .{f});
    std.process.exit(1);
}

const gid = C.sanitize(allocator, gname);
const start_rn = C.sanitize(allocator, found_rules.?[0].branch);

// --- Assemble the standalone C file ---
var file = std.ArrayList(u8){};
const w = &file;
w.appendSlice(allocator, std.fmt.allocPrint(allocator,
    \\/* Generated by koru std/parser `generate` from grammar `{s}`. Do not edit. */
    \\#include <stdint.h>
    \\#include <stddef.h>
    \\#include <stdbool.h>
    \\#include <string.h>
    \\
    \\typedef struct {{ const uint8_t* p; size_t len; }} koru_slice;
    \\typedef struct {{ size_t end; koru_slice val; }} koru_pres;
    \\typedef struct {{ size_t pos; const char* expected; }} koru_perr;
    \\
    \\static bool __koru_lit_eq(const uint8_t* a, size_t alen, const char* b, size_t blen) {{
    \\    if (alen != blen) return false;
    \\    return memcmp(a, b, alen) == 0;
    \\}}
    \\
    \\
, .{gname}) catch unreachable) catch unreachable;

// Forward declarations (mutual recursion between rule fns).
for (found_rules.?) |*r| {
    const rn = C.sanitize(allocator, r.branch);
    w.appendSlice(allocator, std.fmt.allocPrint(allocator, "static bool __koru_pr_{s}(const uint8_t* input, size_t len, size_t pos, koru_perr* err, koru_pres* out);\n", .{rn}) catch unreachable) catch unreachable;
}
w.appendSlice(allocator, "\n/* --- terminal matchers (anchored-prefix DFAs) --- */\n") catch unreachable;
w.appendSlice(allocator, matchers.items) catch unreachable;
w.appendSlice(allocator, "\n/* --- rule functions --- */\n") catch unreachable;
w.appendSlice(allocator, out.items) catch unreachable;

// Public API: parse the whole input against the start rule (first rule).
w.appendSlice(allocator, std.fmt.allocPrint(allocator,
    \\
    \\/* --- public API --- */
    \\typedef struct {{
    \\    bool ok;
    \\    koru_slice value;      /* valid iff ok */
    \\    size_t line, col;      /* valid iff !ok */
    \\    const char* expected;  /* valid iff !ok */
    \\    koru_slice found;      /* valid iff !ok */
    \\}} koru_parse_result;
    \\
    \\koru_parse_result koru_parse_{s}(const uint8_t* input, size_t len) {{
    \\    koru_perr err = {{ 0, 0 }};
    \\    koru_pres res;
    \\    koru_parse_result r;
    \\    if (__koru_pr_{s}(input, len, 0, &err, &res)) {{
    \\        if (res.end == len) {{ r.ok = true; r.value = res.val; return r; }}
    \\        if (err.expected == 0 || res.end > err.pos) {{ err.pos = res.end; err.expected = "end of input"; }}
    \\    }}
    \\    r.ok = false;
    \\    {{ size_t l = 1, c = 1; size_t ep = err.pos < len ? err.pos : len;
    \\      for (size_t k = 0; k < ep; k++) {{ if (input[k] == '\n') {{ l++; c = 1; }} else c++; }}
    \\      r.line = l; r.col = c; }}
    \\    r.expected = err.expected ? err.expected : "";
    \\    if (err.pos < len) {{ koru_slice f = {{ input + err.pos, 1 }}; r.found = f; }}
    \\    else {{ koru_slice f = {{ (const uint8_t*)"end of input", 12 }}; r.found = f; }}
    \\    return r;
    \\}}
    \\
    \\#ifndef KORU_PARSER_NO_MAIN
    \\#include <stdio.h>
    \\int main(int argc, char** argv) {{
    \\    if (argc < 2) {{ fprintf(stderr, "usage: %s <input>\n", argv[0]); return 2; }}
    \\    const char* s = argv[1];
    \\    koru_parse_result r = koru_parse_{s}((const uint8_t*)s, strlen(s));
    \\    if (r.ok) {{ printf("OK: %.*s\n", (int)r.value.len, r.value.p); return 0; }}
    \\    printf("PARSE-ERROR %zu:%zu expected %s found %.*s\n", r.line, r.col, r.expected, (int)r.found.len, r.found.p);
    \\    return 1;
    \\}}
    \\#endif
    \\
, .{ gid, start_rn, gid }) catch unreachable) catch unreachable;

// --- Write it out ---
const path = std.fmt.allocPrint(allocator, "{s}.c", .{gid}) catch unreachable;
const cwd = std.fs.cwd();
const f = cwd.createFile(path, .{}) catch |err| {
    std.debug.print("std/parser generate: cannot write {s}: {s}\n", .{ path, @errorName(err) });
    std.process.exit(1);
};
defer f.close();
f.writeAll(file.items) catch |err| {
    std.debug.print("std/parser generate: write failed: {s}\n", .{@errorName(err)});
    std.process.exit(1);
};

std.debug.print("std/parser generate: grammar '{s}' -> {s} ({d} bytes, {d} rule(s), start rule '{s}')\n", .{ gname, path, file.items.len, found_rules.?.len, found_rules.?[0].branch });

// A one-shot command: exit straight away. This also skips the backend's GPA
// teardown leak-check — the emitter allocates freely on the compile arena
// and never frees (the process is about to die), which is correct for a
// run-once-then-exit command, not a leak worth reporting.
std.process.exit(0);

if (validateMocks(allocator, program, mocks, source)) {
    return .{ .ok = .{} };
}
return .{ .failed = "Mock shape validation failed" };

const std_import = @import("std");
const ast = @import("ast");
const ast_functional = @import("ast_functional");
const parser_impl = @import("parser");
const emitter_helpers = @import("emitter_helpers");

// Get the flow from the item
const flow = if (item.* == .flow)
    &item.flow
else
    return .{};

// Position-agnostic: the runner lifts nested sites into a synthetic
// top-level flow, so `invocation` IS the flow's own invocation at every depth.
_ = invocation;

// Get test name from expr parameter
const test_name = expr;

// Storage for parsed items
var cloned_mocks = std_import.ArrayList(ast.Item).initCapacity(allocator, 8) catch unreachable;
var cloned_flows = std_import.ArrayList(ast.Item).initCapacity(allocator, 8) catch unreachable;

// Parse the source block
parse_block: {
    if (source.text.len == 0) break :parse_block;

    var p = parser_impl.Parser.init(allocator, source.text, "__test__.kz", &[_][]const u8{}, null) catch {
        break :parse_block;
    };
    defer p.deinit();

    var result = p.parse() catch {
        break :parse_block;
    };
    defer result.deinit();

    // Clone parsed items to owned memory
    for (result.source_file.items) |*parsed_item| {
        switch (parsed_item.*) {
            .immediate_impl => {
                const cloned = ast_functional.cloneItem(allocator, parsed_item) catch continue;
                cloned_mocks.append(allocator, cloned) catch {};
            },
            .flow => {
                const cloned = ast_functional.cloneItem(allocator, parsed_item) catch continue;
                cloned_flows.append(allocator, cloned) catch {};
            },
            else => {},
        }
    }
}

// ==========================================================================
// NEW ARCHITECTURE: Clone program, substitute mocks, emit test module
// ==========================================================================

// Generate unique test module name from test_name
var test_module_name_buf: [128]u8 = undefined;
var test_module_name_len: usize = 0;
const prefix = "test_";
@memcpy(test_module_name_buf[0..prefix.len], prefix);
test_module_name_len = prefix.len;
// Sanitize test name: replace spaces/special chars with underscores
for (test_name) |c| {
    if (test_module_name_len >= test_module_name_buf.len - 8) break;
    if ((c >= 'a' and c <= 'z') or (c >= 'A' and c <= 'Z') or (c >= '0' and c <= '9')) {
        test_module_name_buf[test_module_name_len] = c;
        test_module_name_len += 1;
    } else if (c == ' ' or c == '-' or c == '_') {
        test_module_name_buf[test_module_name_len] = '_';
        test_module_name_len += 1;
    }
}
const suffix = "_module";
@memcpy(test_module_name_buf[test_module_name_len..test_module_name_len + suffix.len], suffix);
test_module_name_len += suffix.len;
const test_module_name = test_module_name_buf[0..test_module_name_len];

// Clone program AST
const cloned_program = ast_functional.cloneSourceFile(allocator, program) catch {
    return .{};
};

// Build test module items: program items with mocks substituted
var test_module_items = std_import.ArrayList(ast.Item).initCapacity(allocator, cloned_program.items.len + cloned_mocks.items.len) catch unreachable;

// Helper to check if an impl matches any mock (mocks are now immediate_impl items)
const matchesMock = struct {
    fn check(impl_path: *const ast.DottedPath, mocks: []const ast.Item) bool {
        for (mocks) |mock_item| {
            if (mock_item == .immediate_impl) {
                const mock_path = &mock_item.immediate_impl.event_path;
                if (impl_path.segments.len == mock_path.segments.len) {
                    var all_match = true;
                    for (impl_path.segments, mock_path.segments) |a, b| {
                        if (!std_import.mem.eql(u8, a, b)) {
                            all_match = false;
                            break;
                        }
                    }
                    if (all_match) return true;
                }
            }
        }
        return false;
    }
};

// Add cloned program items, filtering out impls that are mocked
// Also skip top-level flows, module_decls, and imports that shouldn't be in the flat test module
for (cloned_program.items) |p_item| {
    switch (p_item) {
        .flow => |f| {
            // Skip top-level flows (they contain ~test), but keep impl flows (impl_of set)
            if (f.impl_of) |*impl_path| {
                // Only add if NOT mocked
                if (!matchesMock.check(impl_path, cloned_mocks.items)) {
                    test_module_items.append(allocator, p_item) catch {};
                }
            }
            // else: top-level flow, skip
        },
        .module_decl => {},  // Skip module declarations (test module is flat)
        .import_decl => {},  // Skip imports (test module uses parent's imports)
        .immediate_impl => |ii| {
            // Only add if NOT mocked
            if (!matchesMock.check(&ii.event_path, cloned_mocks.items)) {
                test_module_items.append(allocator, p_item) catch {};
            }
        },
        else => test_module_items.append(allocator, p_item) catch {},
    }
}

// Add mock immediate_impls (these override any filtered out)
for (cloned_mocks.items) |m| {
    test_module_items.append(allocator, m) catch {};
}

if (!validateMocks(allocator, &cloned_program, cloned_mocks.items, &source)) {
    @panic("Mock shape validation failed");
}

const type_registry_module = @import("type_registry");
var local_registry_ptr: ?*type_registry_module.TypeRegistry = null;
const type_registry_ptr: ?*type_registry_module.TypeRegistry = if (program.type_registry) |ptr| blk: {
    break :blk @ptrCast(@alignCast(ptr));
} else blk: {
    local_registry_ptr = allocator.create(type_registry_module.TypeRegistry) catch unreachable;
    local_registry_ptr.?.* = type_registry_module.TypeRegistry.init(allocator);
    local_registry_ptr.?.populateFromAST(program.items) catch unreachable;
    break :blk local_registry_ptr.?;
};
defer if (local_registry_ptr) |ptr| {
    ptr.deinit();
    allocator.destroy(ptr);
};

// Emit the test module using emitModuleSubset
// Pass the original main module name so event references are redirected to test module
const test_module_code = emitter_helpers.emitModuleSubset(
    allocator,
    test_module_items.items,
    test_module_name,
    type_registry_ptr,
    program.main_module_name,  // original main module name for event redirection
) catch |err| {
    // Loud failure: silently skipping emission would mean the test block
    // never exists — a test that "passes" by not being generated.
    std_import.debug.print("FATAL: emitModuleSubset failed in test: {s}\n", .{@errorName(err)});
    @panic("test transform: emitModuleSubset failed — see error above");
};

// Run transforms on test flows (for assert -> inline_code, etc.)
var flow_items = std_import.ArrayList(ast.Item).initCapacity(allocator, cloned_flows.items.len + test_module_items.items.len) catch unreachable;
for (cloned_flows.items) |f| flow_items.append(allocator, f) catch {};
// Include test module items for event resolution during transform
for (test_module_items.items) |ti| flow_items.append(allocator, ti) catch {};

const flow_program = allocator.create(ast.Program) catch unreachable;
flow_program.* = ast.Program{
    .items = flow_items.items,
    .module_annotations = &[_][]const u8{},
    .main_module_name = test_module_name,
    .allocator = allocator,
    .type_registry = program.type_registry,
};

const backend_output = @import("backend_output_emitted.zig");
const transformed_program = backend_output.run_pass("transform", flow_program, allocator) catch |err| {
    // Loud failure: continuing with untransformed test flows would emit
    // raw transform invocations into the test block.
    std_import.debug.print("FATAL: transform pass failed in test: {}\n", .{err});
    @panic("test transform: inner transform pass failed — see error above");
};

// ==========================================================================
// NEW: Walk TRANSFORMED flows for purity (after transforms!)
// At this point, assert() is already inline_code - won't trigger purity check
// ==========================================================================

std_import.debug.print("[TEST] Building mock lookup map\n", .{});

// Build mock lookup map for purity checking (still needed to know what's mocked)
var mock_paths = std_import.StringHashMap(ast.BranchConstructor).init(allocator);
for (cloned_mocks.items) |mock_item| {
    if (mock_item == .immediate_impl) {
        const ii = mock_item.immediate_impl;
        var path_buf = std_import.ArrayList(u8).initCapacity(allocator, 64) catch unreachable;
        for (ii.event_path.segments, 0..) |seg, i| {
            if (i > 0) path_buf.append(allocator, '.') catch {};
            path_buf.appendSlice(allocator, seg) catch {};
        }
        mock_paths.put(path_buf.items, ii.value) catch {};
    }
}

// Also scan program for constant events (immediate_impl items)
const scanForConstants = struct {
    fn scan(items: []const ast.Item, paths: *std_import.StringHashMap(ast.BranchConstructor), alloc: std_import.mem.Allocator) void {
        for (items) |prog_item| {
            switch (prog_item) {
                .immediate_impl => |ii| {
                    var path_buf = std_import.ArrayList(u8).initCapacity(alloc, 64) catch unreachable;
                    for (ii.event_path.segments, 0..) |seg, i| {
                        if (i > 0) path_buf.append(alloc, '.') catch {};
                        path_buf.appendSlice(alloc, seg) catch {};
                    }
                    paths.put(path_buf.items, ii.value) catch {};
                },
                .module_decl => |mod| {
                    scan(mod.items, paths, alloc);
                },
                else => {},
            }
        }
    }
};
scanForConstants.scan(program.items, &mock_paths, allocator);

// Debug: Show all items in transformed program
std_import.debug.print("[TEST] Transformed program has {d} items:\n", .{transformed_program.items.len});
for (transformed_program.items, 0..) |t_item, idx| {
    const item_type = switch (t_item) {
        .flow => "flow",
        .immediate_impl => "immediate_impl",
        .event_decl => "event_decl",
        .proc_decl => "proc_decl",
        .module_decl => "module_decl",
        .inline_code => "inline_code",
        else => "other",
    };
    std_import.debug.print("[TEST]   [{d}] {s}\n", .{idx, item_type});
    if (t_item == .flow) {
        std_import.debug.print("[TEST]       invocation: {s}\n", .{t_item.flow.inv().path.segments[0]});
    }
    if (t_item == .inline_code) {
        const preview_len = @min(50, t_item.inline_code.code.len);
        std_import.debug.print("[TEST]       code: {s}...\n", .{t_item.inline_code.code[0..preview_len]});
    }
}

// Find ONLY flows that originated from the test source block
var transformed_flows = std_import.ArrayList(*const ast.Flow).initCapacity(allocator, 8) catch unreachable;
for (transformed_program.items) |*t_item| {
    if (t_item.* == .flow) {
        if (std_import.mem.eql(u8, t_item.flow.location.file, "__test__.kz")) {
            transformed_flows.append(allocator, &t_item.flow) catch {};
        }
    }
}

std_import.debug.print("[TEST] Found {d} transformed flows\n", .{transformed_flows.items.len});

var impure_events = std_import.ArrayList([]const u8).initCapacity(allocator, 8) catch unreachable;
for (transformed_flows.items) |t_flow| {
    walkFlowForPurity(t_flow, &mock_paths, &impure_events, transformed_program.items, allocator);
}
std_import.debug.print("[TEST] Purity walk complete, {d} impure events\n", .{impure_events.items.len});

// Error on impure events without mocks
if (impure_events.items.len > 0) {
    var err_msg = std_import.ArrayList(u8).initCapacity(allocator, 256) catch unreachable;
    err_msg.appendSlice(allocator, "Test '") catch {};
    err_msg.appendSlice(allocator, test_name) catch {};
    err_msg.appendSlice(allocator, "' has impure events without mocks:\n") catch {};
    for (impure_events.items) |event_path| {
        err_msg.appendSlice(allocator, "  - ") catch {};
        err_msg.appendSlice(allocator, event_path) catch {};
        err_msg.appendSlice(allocator, "\n") catch {};
    }
    @panic(err_msg.items);
}

// ==========================================================================
// Emit test flow using test module prefix
// ==========================================================================

// Growable: generated test code has no natural size ceiling.
var code_emitter = emitter_helpers.CodeEmitter.initGrowable(allocator, 16 * 1024) catch unreachable;

// Dupe the test module name for the context (it needs to outlive the stack buffer)
const module_prefix_owned = allocator.dupe(u8, test_module_name) catch unreachable;

var emit_ctx = emitter_helpers.EmissionContext{
    .allocator = allocator,
    .indent_level = 1,
    .ast_items = test_module_items.items,  // Use test module items for resolution
    .main_module_name = module_prefix_owned,
    .module_prefix = module_prefix_owned,  // KEY: Use test module for local references!
    .is_sync = true,
    .type_registry = type_registry_ptr,
};
code_emitter.indent_level = 1;

// Emit each transformed flow using the test module prefix
for (transformed_flows.items) |t_flow| {
    emitter_helpers.emitFlow(&code_emitter, &emit_ctx, t_flow) catch {};
}

const flow_code = code_emitter.getOutput();

// Build final test code: test module + test block
const test_code = std_import.fmt.allocPrint(
    allocator,
    \\{s}
    \\test "{s}" {{
    \\{s}}}
    ,
    .{ test_module_code, test_name, flow_code }
) catch unreachable;

// Create inline_code item
const new_item = ast.Item{ .inline_code = ast.InlineCode{
    .code = test_code,
    .location = flow.location,
    .module = allocator.dupe(u8, flow.module) catch unreachable,
} };

return .{ .replacement = new_item };

const std_import = @import("std");
const ast = @import("ast");

// Get the flow from the item
const flow = if (item.* == .flow)
    &item.flow
else
    return .{};

// Position-agnostic: the runner lifts nested sites into a synthetic
// top-level flow, so `invocation` IS the flow's own invocation at every depth.
// One write-back path: a statement-shaped inline_body (the old fork used
// preamble_code at top level and a raw inline_code node in pipelines —
// same emitted statement, two encodings). Continuations are KEPT so a
// chained `assert(x) |> next()` keeps running its chain at any depth.
_ = invocation;

// Build assertion code - use idiomatic Zig testing assertions.
// //@koru:inline_stmt marks it statement-shaped for the inline emitter.
const assert_code = std_import.fmt.allocPrint(
    allocator,
    "//@koru:inline_stmt\ntry @import(\"std\").testing.expect({s});",
    .{ expr }
) catch unreachable;

const new_inv_annotations = allocator.alloc([]const u8, flow.inv().annotations.len + 1) catch unreachable;
for (flow.inv().annotations, 0..) |ann, idx| {
    new_inv_annotations[idx] = ann;
}
new_inv_annotations[flow.inv().annotations.len] = allocator.dupe(u8, "@pass_ran(\"transform\")") catch unreachable;

const new_invocation = ast.Invocation{
    .path = flow.inv().path,
    .args = &[_]ast.Arg{},
    .annotations = new_inv_annotations,
    .inserted_by_tap = flow.inv().inserted_by_tap,
    .from_opaque_tap = flow.inv().from_opaque_tap,
    .inline_body = assert_code,
};

const transformed_flow = ast.Flow{
    .body = ast.rootSite(new_invocation, flow.body.continuations, flow.location),
    .annotations = flow.annotations,
    .pre_label = flow.pre_label,
    .super_shape = flow.super_shape,
    .inline_body = assert_code,
    .is_pure = true,
    .is_transitively_pure = true,
    .impl_of = flow.impl_of,
    .location = flow.location,
    .module = flow.module,
};

const new_item = ast.Item{ .flow = transformed_flow };

return .{ .replacement = new_item };

// Always print to verify the integration works
log.debug("\n[INTER] inter:start called with {d} contexts\n", .{contexts.len});

// CompilerEnv is provided globally by the compiler backend
const env = @import("root").CompilerEnv;

// Check if --inter flag is set
if (!env.hasFlag("inter")) {
    log.debug("[INTER] --inter flag not set, skipping\n", .{});
    return .{ .skipped = .{} };
}

std.debug.print("\n", .{});
std.debug.print("╔══════════════════════════════════════════════════════════════╗\n", .{});
std.debug.print("║  KORU INTERACTIVE COMPILER                                   ║\n", .{});
std.debug.print("║  --inter mode activated                                      ║\n", .{});
std.debug.print("╠══════════════════════════════════════════════════════════════╣\n", .{});
std.debug.print("║  Pipeline stages captured: {d:<33}║\n", .{contexts.len});
std.debug.print("╚══════════════════════════════════════════════════════════════╝\n", .{});
std.debug.print("\n", .{});

// List what we have
for (contexts, 0..) |ctx, i| {
    if (ctx.current_pass) |pass| {
        std.debug.print("  {d}. {s:<20} ({d} passes, {d} items)\n", .{i + 1, pass, ctx.passes_completed, ctx.ast.items.len});
    } else {
        std.debug.print("  {d}. (unnamed)            ({d} passes, {d} items)\n", .{i + 1, ctx.passes_completed, ctx.ast.items.len});
    }
}

std.debug.print("\n", .{});

// Interactive REPL loop
std.debug.print("Type 'h' for help, 'q' to quit.\n\n", .{});
const stdin = std.fs.File.stdin();
while (true) {
    std.debug.print("inter> ", .{});

    var buf: [256]u8 = undefined;
    const n = stdin.read(&buf) catch break;
    if (n == 0) break;  // EOF

    // Find first non-whitespace char
    var cmd: u8 = 0;
    for (buf[0..n]) |c| {
        if (c != ' ' and c != '\t' and c != '\n' and c != '\r') {
            cmd = c;
            break;
        }
    }

    if (cmd == 'q' or cmd == 'Q') {
        std.debug.print("Exiting inter mode.\n", .{});
        break;
    }

    if (cmd == 'h' or cmd == 'H' or cmd == '?') {
        std.debug.print("Commands:\n", .{});
        std.debug.print("  1-{d}  Show stats for stage N\n", .{contexts.len});
        std.debug.print("  h    Help\n", .{});
        std.debug.print("  q    Quit\n", .{});
        continue;
    }

    // Check for digit 1-9
    if (cmd >= '1' and cmd <= '9') {
        const stage_idx = cmd - '1';
        if (stage_idx < contexts.len) {
            const ctx = contexts[stage_idx];
            std.debug.print("\n=== Stage {d} Stats ===\n", .{stage_idx + 1});
            if (ctx.current_pass) |pass| {
                std.debug.print("  Current pass: {s}\n", .{pass});
            }
            std.debug.print("  Passes completed: {d}\n", .{ctx.passes_completed});
            std.debug.print("  Total items: {d}\n", .{ctx.ast.items.len});

            // Count item types
            var events: usize = 0;
            var procs: usize = 0;
            var flows: usize = 0;
            var flows_transformed: usize = 0;
            var imports: usize = 0;
            var host_lines: usize = 0;
            var immediate_impls: usize = 0;
            var modules: usize = 0;

            // Helper to count a flow and check if transformed
            const countFlow = struct {
                fn count(flow: anytype, f: *usize, ft: *usize) void {
                    f.* += 1;
                    if (flow.inline_body != null) ft.* += 1;
                }
            }.count;

            for (ctx.ast.items) |item| {
                switch (item) {
                    .event_decl => events += 1,
                    .proc_decl => procs += 1,
                    .flow => |f| countFlow(f, &flows, &flows_transformed),
                    .import_decl => imports += 1,
                    .host_line => host_lines += 1,
                    .immediate_impl => immediate_impls += 1,
                    .module_decl => |mod| {
                        modules += 1;
                        for (mod.items) |mod_item| {
                            switch (mod_item) {
                                .event_decl => events += 1,
                                .proc_decl => procs += 1,
                                .flow => |f| countFlow(f, &flows, &flows_transformed),
                                .import_decl => imports += 1,
                                .host_line => host_lines += 1,
                                .immediate_impl => immediate_impls += 1,
                                else => {},
                            }
                        }
                    },
                    else => {},
                }
            }

            std.debug.print("  Modules: {d}\n", .{modules});
            std.debug.print("  Events: {d}\n", .{events});
            std.debug.print("  Procs: {d}\n", .{procs});
            std.debug.print("  Flows: {d} ({d} transformed)\n", .{flows, flows_transformed});
            if (immediate_impls > 0) std.debug.print("  Immediate impls: {d}\n", .{immediate_impls});
            std.debug.print("  Host lines: {d}\n", .{host_lines});
            std.debug.print("  Errors: {d}, Warnings: {d}\n", .{ctx.errors.items.len, ctx.warnings.items.len});
            std.debug.print("\n", .{});
        } else {
            std.debug.print("Stage {d} doesn't exist (max: {d})\n", .{stage_idx + 1, contexts.len});
        }
        continue;
    }

    if (cmd != 0) {
        std.debug.print("Unknown command '{c}'. Type 'h' for help.\n", .{cmd});
    }
}

return .{ .launched = .{} };

