    {{ continuations["then"].continue }}
} else {
    {{ continuations["else"].continue }}
}

if ({{ expr }}) {
    {{ continuations["then"].continue }}
} else {
    {{ continuations["else"].continue }}
}

{% for arm in continuations["c"] %}{% if arm.guard != "" %}if ({{ arm.guard }}) {
    {{ arm.bind }}{{ arm.continue }}
}
{% else %}{
    {{ arm.bind }}{{ arm.continue }}
}{% endif %}{% endfor %}

for ({{ expr }}) |__koru_item| {
    {% for h in effects["each"] %}{{ h.inlined_link[scope] }}(__koru_item);
    {% endfor %}
}
{{ continuations["done"].continue }}

{% const __koru_range = parse_range(expr) %}{% if __koru_range.is_range %}for (let __koru_item = {{ __koru_range.lo }}; __koru_item < {{ __koru_range.hi }}; __koru_item++) {% else %}for (const __koru_item of {{ expr }}) {% endif %}{
    {% for h in effects["each"] %}{{ h.inlined_link[scope] }}(__koru_item);
    {% endfor %}
